import { apiPost } from "./api.js";

/**
 * Document parsing bridge (Vance's enhanced capability).
 *
 * PRODUCTION PATH
 * ---------------
 * The PDF is uploaded to the backend, which calls the Anthropic Claude API
 * **server-side** (the API key never touches the browser). Claude reads each
 * passport page and returns structured rows. The server prompt instructs Claude
 * to return ONLY JSON:
 *
 *   [{ "fullName", "passportNumber", "nationality", "passportExpiry", "confidence" }]
 *
 * Low-confidence rows (< 0.85) are flagged for manual review, satisfying the
 * "blurry document" alternative flow from Use Case 1.
 *
 * DEMO PATH
 * ---------
 * When no backend is reachable (USE_SIMULATION = true), we return realistic
 * dummy rows so the page is immediately runnable with built-in state.
 */

const USE_SIMULATION = true; // flip to false once the backend is live

const SIMULATED_ROWS = [
  { fullName: "Lim Wei Jie",   passportNumber: "S1234567A", nationality: "Singapore", passportExpiry: "2029-08-12", confidence: 0.99 },
  { fullName: "Chen Hao Ming", passportNumber: "E2233445C", nationality: "China",     passportExpiry: null,         confidence: 0.62 },
  { fullName: "Tan Siew Ling", passportNumber: "S9876543B", nationality: "Singapore", passportExpiry: "2031-03-04", confidence: 0.92 },
  { fullName: "Ng Soo Peng",   passportNumber: "S4456781C", nationality: "Singapore", passportExpiry: "2028-11-20", confidence: 0.97 },
  { fullName: "Wong Pei Shan", passportNumber: "S5567892D", nationality: "Singapore", passportExpiry: "2030-06-15", confidence: 0.94 },
  { fullName: "Goh Mei Ling",  passportNumber: "S6678903E", nationality: "Singapore", passportExpiry: "2027-02-28", confidence: 0.88 },
  { fullName: "Koh Siew Wah",  passportNumber: "K9012345F", nationality: "Malaysia",  passportExpiry: null,         confidence: 0.71 },
  { fullName: "Phua Yong Min", passportNumber: "S7789014G", nationality: "Singapore", passportExpiry: "2032-09-09", confidence: 0.96 },
  { fullName: "Sim Tian Kee",  passportNumber: "S8890125H", nationality: "Singapore", passportExpiry: "2029-12-01", confidence: 0.91 },
  { fullName: "Yeo Pei Lin",   passportNumber: "S9901236J", nationality: "Singapore", passportExpiry: "2030-04-17", confidence: 0.95 },
  { fullName: "Wong Hui Bin",  passportNumber: "S1012347K", nationality: "Singapore", passportExpiry: "2028-07-22", confidence: 0.93 },
  { fullName: "Guo Wei Jian",  passportNumber: "G2123458L", nationality: "China",     passportExpiry: "2031-01-30", confidence: 0.69 },
];

const wait = (ms) => new Promise((r) => setTimeout(r, ms));

/**
 * Parse a single uploaded file into delegate rows.
 * @returns {Promise<{rows: Array, totalCount: number}>}
 */
export async function parseDocument(file, { documentId, tripId } = {}) {
  if (!USE_SIMULATION && documentId) {
    const data = await apiPost(`/documents/${documentId}/parse`, { tripId });
    return { rows: data.rows, totalCount: data.rows.length };
  }

  // --- simulated extraction (immediately runnable) ---
  await wait(1400 + Math.random() * 1200); // mimic network + model latency
  // Vary how many rows each file "contains" so multiple uploads look distinct.
  const count = file?.name?.includes("batch_2") ? 12 : SIMULATED_ROWS.length;
  const rows = SIMULATED_ROWS.slice(0, count).map((r, i) => ({
    id: `${file?.name || "file"}-${i}`,
    needsReview: r.confidence < 0.85,
    ...r,
  }));
  return { rows, totalCount: count };
}

/**
 * Minimal API client. Reads the JWT from memory/session and attaches it.
 * Swap BASE_URL for your deployed Express origin.
 */
const BASE_URL = import.meta.env.VITE_API_URL || "/api";

function authHeader() {
  const token = sessionStorage.getItem("mg_token");
  return token ? { Authorization: `Bearer ${token}` } : {};
}

export async function apiGet(path) {
  const res = await fetch(`${BASE_URL}${path}`, { headers: { ...authHeader() } });
  if (!res.ok) throw new Error(`GET ${path} failed (${res.status})`);
  return res.json();
}

export async function apiPost(path, body, isForm = false) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method: "POST",
    headers: isForm
      ? { ...authHeader() }
      : { "Content-Type": "application/json", ...authHeader() },
    body: isForm ? body : JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`POST ${path} failed (${res.status})`);
  return res.json();
}

export async function apiPatch(path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json", ...authHeader() },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`PATCH ${path} failed (${res.status})`);
  return res.json();
}

/**
 * Renders a pill in the MusterGo five-state status system.
 * Pass either a known `state` or use the confidence helper below.
 */
const STATE_MAP = {
  PRESENT: { cls: "badge-present", label: "Present" },
  MISSING: { cls: "badge-missing", label: "Missing" },
  UNASSIGNED: { cls: "badge-unassigned", label: "Unassigned" },
  REVIEW: { cls: "badge-review", label: "Review" },
  NORMAL: { cls: "badge-normal", label: "Normal" },
  CRITICAL: { cls: "badge-missing", label: "Critical" },
  LOW: { cls: "badge-neutral", label: "Low" },
  RESOLVED: { cls: "badge-present", label: "Resolved" },
  OPEN: { cls: "badge-missing", label: "Open" },
};

export default function StatusBadge({ state, children }) {
  const def = STATE_MAP[state] || { cls: "badge-neutral", label: state };
  return <span className={"badge " + def.cls}>{children || def.label}</span>;
}

/** Map a 0–1 confidence score to the review/present/missing palette. */
export function ConfidenceBadge({ value }) {
  const pct = Math.round(value * 100);
  let cls = "badge-present";
  if (value < 0.6) cls = "badge-missing";
  else if (value < 0.85) cls = "badge-review";
  return <span className={"badge " + cls + " mono"}>{pct}%</span>;
}

import { NavLink } from "react-router-dom";
import {
  LayoutGrid,
  MapPin,
  FileText,
  AlertTriangle,
  MessageSquare,
  ClipboardCheck,
} from "lucide-react";

/**
 * Left navigation rail. Mirrors the MusterGo admin shell (Screens 2–6).
 * `exceptionCount` drives the red pill on the Exceptions item.
 */
export default function Sidebar({ exceptionCount = 0 }) {
  const items = [
    { to: "/dashboard", label: "Dashboard", icon: LayoutGrid },
    { to: "/trips", label: "Trips", icon: MapPin },
    { to: "/onboarding", label: "Documents", icon: FileText },
    { to: "/exceptions", label: "Exceptions", icon: AlertTriangle, badge: exceptionCount },
    { to: "/assistant", label: "Chat assistant", icon: MessageSquare },
  ];

  return (
    <nav className="sidebar" aria-label="Primary">
      <div className="sidebar-brand wordmark">
        <ClipboardCheck size={22} strokeWidth={2.4} /> MusterGo
      </div>
      {items.map(({ to, label, icon: Icon, badge }) => (
        <NavLink
          key={to}
          to={to}
          className={({ isActive }) => "nav-item" + (isActive ? " active" : "")}
        >
          <Icon size={18} strokeWidth={2} />
          {label}
          {badge ? <span className="nav-badge">{badge}</span> : null}
        </NavLink>
      ))}
    </nav>
  );
}

import { Outlet } from "react-router-dom";
import Sidebar from "./Sidebar.jsx";

/**
 * Admin shell layout. The sidebar persists; routed pages render in <Outlet/>.
 * `exceptionCount` is hard-coded here as demo state; in production it comes
 * from GET /api/trips/:id/dashboard.
 */
export default function Layout() {
  const openExceptions = 3; // demo: matches Screen 2

  return (
    <div className="app-shell">
      <Sidebar exceptionCount={openExceptions} />
      <main className="main">
        <Outlet />
      </main>
    </div>
  );
}

/* ==========================================================================
   MusterGo design tokens — VJMDynamics × SCCCI
   Singpass-inspired clean UI · SCCCI Red primary · five-state status system
   ========================================================================== */

:root {
  /* Brand */
  --scc-red: #e1232a;
  --scc-red-600: #c41d24;
  --scc-red-700: #a3171d;
  --scc-red-tint: #fdecec;
  --scc-red-tint-2: #fbd9da;

  /* Neutrals */
  --ink: #1a1d21;
  --ink-2: #4a5158;
  --ink-3: #6b7280;
  --line: #e6e8eb;
  --line-2: #f0f1f3;
  --bg: #f4f5f7;
  --surface: #ffffff;
  --surface-2: #fafbfc;

  /* Five-state status system */
  --st-present: #16a34a;   /* green   — boarded / present       */
  --st-present-bg: #e7f6ec;
  --st-missing: #e1232a;   /* red     — missing / critical      */
  --st-missing-bg: #fdecec;
  --st-unassigned: #d97706;/* amber   — unassigned / needs coach*/
  --st-unassigned-bg: #fef3e2;
  --st-review: #ca8a04;    /* yellow  — low-confidence / review */
  --st-review-bg: #fdf6e3;
  --st-normal: #7c3aed;    /* violet  — normal-priority exception */
  --st-normal-bg: #f3edfe;
  --st-neutral: #6b7280;   /* slate   — low / resolved / done   */
  --st-neutral-bg: #f1f3f5;

  /* Type */
  --font-display: "Lora", Georgia, serif;
  --font-body: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;

  /* Radius + shadow */
  --r-sm: 8px;
  --r-md: 12px;
  --r-lg: 16px;
  --shadow-sm: 0 1px 2px rgba(16, 24, 40, 0.06);
  --shadow-md: 0 4px 16px rgba(16, 24, 40, 0.08);
  --shadow-lg: 0 12px 32px rgba(16, 24, 40, 0.12);

  --sidebar-w: 232px;
}

* { box-sizing: border-box; }

html, body, #root { height: 100%; }

body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3 { margin: 0; font-weight: 600; }
button { font-family: inherit; cursor: pointer; }
a { color: inherit; }

/* ---- Brand wordmark ---------------------------------------------------- */
.wordmark {
  font-family: var(--font-display);
  font-weight: 700;
  color: var(--scc-red);
  letter-spacing: -0.01em;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

/* ---- Buttons ----------------------------------------------------------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: var(--r-sm);
  padding: 10px 16px;
  font-size: 14px;
  font-weight: 600;
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--scc-red); color: #fff; }
.btn-primary:hover { background: var(--scc-red-600); }
.btn-dark { background: var(--ink); color: #fff; }
.btn-dark:hover { background: #000; }
.btn-ghost { background: #fff; color: var(--ink); border-color: var(--line); }
.btn-ghost:hover { background: var(--surface-2); }
.btn-block { width: 100%; }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }

/* ---- Cards ------------------------------------------------------------- */
.card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-sm);
}

/* ---- App shell --------------------------------------------------------- */
.app-shell { display: flex; min-height: 100vh; }

.sidebar {
  width: var(--sidebar-w);
  flex-shrink: 0;
  background: var(--surface);
  border-right: 1px solid var(--line);
  padding: 20px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.sidebar-brand { padding: 6px 10px 20px; font-size: 22px; }
.nav-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: var(--r-sm);
  color: var(--ink-2);
  text-decoration: none;
  font-size: 14px;
  font-weight: 500;
  position: relative;
}
.nav-item:hover { background: var(--surface-2); }
.nav-item.active { background: var(--scc-red-tint); color: var(--scc-red); font-weight: 600; }
.nav-badge {
  margin-left: auto;
  background: var(--scc-red);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  border-radius: 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
}

.main { flex: 1; min-width: 0; }
.page { padding: 32px 40px; max-width: 1180px; }
.page-eyebrow {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.page-title { font-size: 28px; margin: 4px 0 2px; }
.page-sub { color: var(--ink-3); font-size: 14px; }

/* ---- Status + confidence badges --------------------------------------- */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 999px;
  line-height: 1;
}
.badge-present    { color: var(--st-present);    background: var(--st-present-bg); }
.badge-missing    { color: var(--st-missing);    background: var(--st-missing-bg); }
.badge-unassigned { color: var(--st-unassigned); background: var(--st-unassigned-bg); }
.badge-review     { color: var(--st-review);     background: var(--st-review-bg); }
.badge-normal     { color: var(--st-normal);     background: var(--st-normal-bg); }
.badge-neutral    { color: var(--st-neutral);    background: var(--st-neutral-bg); }

/* ---- Tables ------------------------------------------------------------ */
.table { width: 100%; border-collapse: collapse; font-size: 14px; }
.table th {
  text-align: left;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-3);
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
}
.table td { padding: 12px; border-bottom: 1px solid var(--line-2); vertical-align: middle; }
.table tr:last-child td { border-bottom: none; }

/* ---- Avatar ------------------------------------------------------------ */
.avatar {
  width: 28px; height: 28px;
  border-radius: 999px;
  background: var(--st-present-bg);
  color: var(--st-present);
  font-size: 11px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

/* ---- Inputs ------------------------------------------------------------ */
.input, .select {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--r-sm);
  font-size: 14px;
  font-family: inherit;
  background: #fff;
  color: var(--ink);
}
.input:focus, .select:focus { outline: 2px solid var(--scc-red-tint-2); border-color: var(--scc-red); }
.field-label { font-size: 13px; font-weight: 600; margin-bottom: 6px; display: block; }

/* ---- Scaffold (placeholder page) -------------------------------------- */
.scaffold {
  border: 1.5px dashed var(--line);
  border-radius: var(--r-lg);
  padding: 48px;
  text-align: center;
  color: var(--ink-3);
  background: var(--surface-2);
}
.scaffold h2 { color: var(--ink); margin-bottom: 8px; }
.scaffold .owner {
  display: inline-block;
  margin-top: 16px;
  font-size: 12px;
  font-weight: 600;
  color: var(--scc-red);
  background: var(--scc-red-tint);
  padding: 4px 12px;
  border-radius: 999px;
}

/* ---- Utility ----------------------------------------------------------- */
.row { display: flex; align-items: center; gap: 12px; }
.between { justify-content: space-between; }
.muted { color: var(--ink-3); }
.mono { font-variant-numeric: tabular-nums; font-feature-settings: "tnum"; }

@media (max-width: 720px) {
  .sidebar { display: none; }
  .page { padding: 20px; }
}

