/**
 * Real-time channel (Enhanced capability) via Server-Sent Events.
 *
 * SSE is chosen over WebSockets because it runs over plain HTTP/HTTPS and
 * survives restrictive proxies — relevant to the project's "must work behind
 * the China Firewall" requirement. The admin Exception Inbox subscribes to
 * GET /api/exceptions/stream and receives push updates as tickets change.
 */
const clients = new Set();

export function sseHandler(req, res) {
  res.set({
    "Content-Type": "text/event-stream",
    "Cache-Control": "no-cache, no-transform",
    Connection: "keep-alive",
  });
  res.flushHeaders?.();
  res.write(`event: ready\ndata: {"ok":true}\n\n`);

  clients.add(res);
  const keepAlive = setInterval(() => res.write(": ping\n\n"), 25000);

  req.on("close", () => {
    clearInterval(keepAlive);
    clients.delete(res);
  });
}

/** Broadcast an event to every connected admin/staff device. */
export function broadcast(event, payload) {
  const frame = `event: ${event}\ndata: ${JSON.stringify(payload)}\n\n`;
  for (const res of clients) {
    try {
      res.write(frame);
    } catch {
      clients.delete(res);
    }
  }
}

