import { Router } from "express";
import { randomUUID } from "crypto";
import { pool } from "../db/pool.js";
import { requireAuth } from "./auth.js";
import { broadcast } from "./sse.js";

const router = Router();

/** SELECT with the joins the inbox needs. */
const BASE_SELECT = `
  SELECT e.id, e.trip_id, e.issue_type, e.priority, e.status, e.is_critical,
         e.note, e.coach_id, e.created_at, e.resolved_at,
         d.name  AS delegate_name, d.is_vip AS delegate_vip,
         c.label AS coach_label,
         ur.name AS raised_by_name,
         urs.name AS resolved_by_name
  FROM exceptions e
  LEFT JOIN delegates d  ON d.id  = e.delegate_id
  LEFT JOIN coaches   c  ON c.id  = e.coach_id
  LEFT JOIN users     ur ON ur.id = e.raised_by
  LEFT JOIN users     urs ON urs.id = e.resolved_by
`;

const shape = (r) => ({
  id: r.id,
  tripId: r.trip_id,
  issueType: r.issue_type,
  priority: r.priority,
  status: r.status,
  isCritical: !!r.is_critical,
  note: r.note,
  delegate: r.delegate_name ? { name: r.delegate_name, vip: !!r.delegate_vip } : null,
  coach: r.coach_label || null,
  raisedBy: r.raised_by_name || null,
  resolvedBy: r.resolved_by_name || null,
  createdAt: r.created_at,
  resolvedAt: r.resolved_at,
});

// All routes require a valid JWT.
router.use(requireAuth);

/** GET /api/exceptions — list + summary counts, with filters. */
router.get("/", async (req, res, next) => {
  try {
    const { tripId, status, priority, coachId } = req.query;
    const where = ["e.deleted_at IS NULL OR e.status = 'CANCELLED'"];
    const params = {};
    // Show everything except hard-deleted; CANCELLED stays visible for audit.
    const filters = [];
    if (tripId)   { filters.push("e.trip_id = :tripId"); params.tripId = tripId; }
    if (status)   { filters.push("e.status = :status"); params.status = status; }
    if (priority) { filters.push("e.priority = :priority"); params.priority = priority; }
    if (coachId)  { filters.push("e.coach_id = :coachId"); params.coachId = coachId; }
    const whereSql = filters.length ? "WHERE " + filters.join(" AND ") : "";

    const [rows] = await pool.query(
      `${BASE_SELECT} ${whereSql} ORDER BY FIELD(e.priority,'CRITICAL','NORMAL','LOW'), e.created_at DESC`,
      params
    );

    // Summary counts are computed over the trip (not the active filter).
    const sumParams = tripId ? { tripId } : {};
    const sumWhere = tripId ? "WHERE trip_id = :tripId" : "";
    const [[summary]] = await pool.query(
      `SELECT
         COUNT(*) AS \`all\`,
         SUM(priority = 'CRITICAL') AS critical,
         SUM(status = 'OPEN')       AS open_count,
         SUM(status = 'RESOLVED')   AS resolved
       FROM exceptions ${sumWhere}`,
      sumParams
    );

    res.json({
      count: rows.length,
      summary: {
        all: Number(summary.all) || 0,
        critical: Number(summary.critical) || 0,
        open: Number(summary.open_count) || 0,
        resolved: Number(summary.resolved) || 0,
      },
      items: rows.map(shape),
    });
  } catch (e) { next(e); }
});

/** GET /api/exceptions/active — unresolved tickets (cross-device sync). */
router.get("/active", async (req, res, next) => {
  try {
    const { tripId } = req.query;
    const params = {};
    let where = "WHERE e.status = 'OPEN'";
    if (tripId) { where += " AND e.trip_id = :tripId"; params.tripId = tripId; }
    const [rows] = await pool.query(`${BASE_SELECT} ${where} ORDER BY e.created_at DESC`, params);
    res.json({ activeCount: rows.length, items: rows.map(shape) });
  } catch (e) { next(e); }
});

/** GET /api/exceptions/:id — single ticket. */
router.get("/:id", async (req, res, next) => {
  try {
    const [rows] = await pool.query(`${BASE_SELECT} WHERE e.id = :id`, { id: req.params.id });
    if (!rows.length) return res.status(404).json({ error: "NOT_FOUND", message: "Ticket not found" });
    res.json(shape(rows[0]));
  } catch (e) { next(e); }
});

/** POST /api/exceptions — create a ticket; markCritical fans out an alert. */
router.post("/", async (req, res, next) => {
  try {
    const { clientRef, tripId, delegateId, coachId, issueType, note, markCritical } = req.body || {};
    if (!tripId || !issueType) {
      return res.status(422).json({ error: "VALIDATION_ERROR", message: "tripId and issueType are required" });
    }
    // Idempotency: a repeated clientRef returns the existing ticket.
    const ref = clientRef || randomUUID();
    const [existing] = await pool.query("SELECT id FROM exceptions WHERE client_ref = :ref", { ref });
    if (existing.length) {
      const [rows] = await pool.query(`${BASE_SELECT} WHERE e.id = :id`, { id: existing[0].id });
      return res.status(200).json(shape(rows[0]));
    }

    const id = randomUUID();
    const priority = markCritical ? "CRITICAL" : "NORMAL";
    const raisedBy = req.user?.sub || "u-admin";

    await pool.query(
      `INSERT INTO exceptions
        (id, trip_id, delegate_id, coach_id, issue_type, priority, status, is_critical, note, raised_by, client_ref)
       VALUES (:id,:tripId,:delegateId,:coachId,:issueType,:priority,'OPEN',:isCritical,:note,:raisedBy,:ref)`,
      { id, tripId, delegateId: delegateId || null, coachId: coachId || null,
        issueType, priority, isCritical: markCritical ? 1 : 0, note: note || null, raisedBy, ref }
    );

    let recipients = 0;
    if (markCritical) {
      // Fan out one alert row per staff/admin on the trip.
      const [staff] = await pool.query("SELECT id FROM users WHERE role IN ('staff','admin')");
      for (const u of staff) {
        await pool.query(
          "INSERT INTO exception_alerts (id, exception_id, recipient_id) VALUES (:aid,:eid,:uid)",
          { aid: randomUUID(), eid: id, uid: u.id }
        );
      }
      recipients = staff.length;
    }

    const [rows] = await pool.query(`${BASE_SELECT} WHERE e.id = :id`, { id });
    const created = shape(rows[0]);
    broadcast(markCritical ? "exception:critical" : "exception:created", { ...created, recipients });
    res.status(201).json({ ...created, alertDispatched: !!markCritical, recipients });
  } catch (e) { next(e); }
});

/** PATCH /api/exceptions/:id — update priority/note/delegate/coach. */
router.patch("/:id", async (req, res, next) => {
  try {
    const fields = [];
    const params = { id: req.params.id };
    for (const [key, col] of [["priority","priority"],["note","note"],["delegateId","delegate_id"],["coachId","coach_id"]]) {
      if (req.body[key] !== undefined) { fields.push(`${col} = :${key}`); params[key] = req.body[key]; }
    }
    if (req.body.priority !== undefined) { fields.push("is_critical = :isCrit"); params.isCrit = req.body.priority === "CRITICAL" ? 1 : 0; }
    if (!fields.length) return res.status(422).json({ error: "VALIDATION_ERROR", message: "No updatable fields" });

    const [r] = await pool.query(`UPDATE exceptions SET ${fields.join(", ")} WHERE id = :id AND status = 'OPEN'`, params);
    if (!r.affectedRows) return res.status(409).json({ error: "CONFLICT", message: "Ticket not open or not found" });

    const [rows] = await pool.query(`${BASE_SELECT} WHERE e.id = :id`, { id: req.params.id });
    broadcast("exception:updated", shape(rows[0]));
    res.json(shape(rows[0]));
  } catch (e) { next(e); }
});

/** PATCH /api/exceptions/:id/resolve — resolve with concurrency guard. */
router.patch("/:id/resolve", async (req, res, next) => {
  try {
    const resolvedBy = req.user?.sub || "u-admin";
    const [r] = await pool.query(
      `UPDATE exceptions
         SET status='RESOLVED', resolved_at=NOW(), resolved_by=:by, resolution_note=:note
       WHERE id=:id AND status='OPEN'`,
      { id: req.params.id, by: resolvedBy, note: req.body?.resolutionNote || null }
    );
    if (!r.affectedRows) return res.status(409).json({ error: "ALREADY_RESOLVED", message: "Ticket already resolved or not found" });
    const [rows] = await pool.query(`${BASE_SELECT} WHERE e.id = :id`, { id: req.params.id });
    broadcast("exception:updated", shape(rows[0]));
    res.json(shape(rows[0]));
  } catch (e) { next(e); }
});

/** DELETE /api/exceptions/:id — soft delete (cancel). */
router.delete("/:id", async (req, res, next) => {
  try {
    const [r] = await pool.query(
      "UPDATE exceptions SET status='CANCELLED', deleted_at=NOW() WHERE id=:id AND deleted_at IS NULL",
      { id: req.params.id }
    );
    if (!r.affectedRows) return res.status(404).json({ error: "NOT_FOUND", message: "Ticket not found" });
    broadcast("exception:updated", { id: req.params.id, status: "CANCELLED" });
    res.json({ id: req.params.id, status: "CANCELLED" });
  } catch (e) { next(e); }
});

export default router;

