import express from "express";
import cors from "cors";
import "dotenv/config";
import { pool, ping } from "../db/pool.js";
import { login, requireAuth } from "./auth.js";
import { sseHandler } from "./sse.js";
import exceptionsRouter from "./exceptions.routes.js";

const app = express();
app.use(cors());
app.use(express.json());

// Health + shared auth stub
app.get("/api/health", async (_req, res) => {
  try { await ping(); res.json({ ok: true, db: "mysql" }); }
  catch { res.status(503).json({ ok: false, db: "unreachable" }); }
});
app.post("/api/auth/login", login);

// Real-time stream (SSE) — auth via query token so EventSource can connect.
app.get("/api/exceptions/stream", sseHandler);

// Delegate lookup for the "Log exception" form (reads Vance's table; here the stub).
app.get("/api/delegates/:tripId", requireAuth, async (req, res, next) => {
  try {
    const [rows] = await pool.query(
      "SELECT id, name, coach_id AS coachId, is_vip AS vip FROM delegates WHERE trip_id = :t ORDER BY name",
      { t: req.params.tripId }
    );
    res.json({ items: rows.map((r) => ({ ...r, vip: !!r.vip })) });
  } catch (e) { next(e); }
});

app.use("/api/exceptions", exceptionsRouter);

// Central error handler
app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: "SERVER_ERROR", message: "Unexpected server error" });
});

const PORT = Number(process.env.PORT || 4000);
app.listen(PORT, () => console.log(`MusterGo exceptions API on :${PORT} (MySQL)`));

