/**
 * Data layer for the Exception Logging feature (Jayden).
 *
 * REAL PATH  — talks to the Node/Express + MySQL API in /server.
 * DEMO PATH  — USE_SIMULATION = true serves in-memory rows so the page is
 *              fully clickable (create / resolve / cancel / filter / live push)
 *              without a running backend. Flip the flag once the API is live.
 */
const BASE_URL = import.meta.env.VITE_API_URL || "/api";
export const USE_SIMULATION = true; // ← flip to false when /server + MySQL are running
export const TRIP_ID = "trip-bj";

function authHeader() {
  const token = sessionStorage.getItem("mg_token");
  return token ? { Authorization: `Bearer ${token}` } : {};
}

async function http(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { "Content-Type": "application/json", ...authHeader() },
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.message || `${method} ${path} failed (${res.status})`);
  return data;
}

/* ============================ SIMULATION STORE ============================ */
const DELEGATES = [
  { id: "d-lim",  name: "Lim Wei Jie",   coach: "Coach 2", vip: true },
  { id: "d-tan",  name: "Tan Boon Keng", coach: "Coach 1", vip: false },
  { id: "d-goh",  name: "Goh Mei Ling",  coach: "Coach 2", vip: false },
  { id: "d-chen", name: "Chen Hao Ming", coach: "Coach 2", vip: false },
  { id: "d-yeo",  name: "Yeo Pei Lin",   coach: "Coach 3", vip: false },
  { id: "d-ng",   name: "Ng Soo Peng",   coach: "Coach 1", vip: false },
  { id: "d-wong", name: "Wong Pei Shan", coach: "Coach 2", vip: false },
  { id: "d-sim",  name: "Sim Tian Kee",  coach: "Coach 3", vip: false },
];

let SIM = [
  mk("e-999","MISSING_PERSON","CRITICAL","OPEN","Not boarded · departure imminent","Lim Wei Jie","Coach 2","Wei Ming","14:18",true),
  mk("e-998","LOST_BADGE","NORMAL","OPEN","Delegate cannot scan QR","Tan Boon Keng","Coach 1","Su Lin","14:24"),
  mk("e-997","FACE_MATCH_FAILED","NORMAL","OPEN","Photo outdated · used QR instead","Goh Mei Ling","Coach 2","Wei Ming","14:11"),
  mk("e-996","DEAD_PHONE","LOW","RESOLVED","Manually counted","Chen Hao Ming","Coach 2","Wei Ming","13:42"),
  mk("e-995","VIP_REQUEST","LOW","RESOLVED","Needs accessible seating","Yeo Pei Lin","Coach 3","Su Lin","09:14"),
  mk("e-994","LOST_BADGE","NORMAL","RESOLVED","Reissued at hotel desk","Ng Soo Peng","Coach 1","Su Lin","08:50"),
  mk("e-993","DEAD_PHONE","LOW","RESOLVED","Charged on coach","Wong Pei Shan","Coach 2","Wei Ming","08:32"),
  mk("e-992","MISSING_PERSON","NORMAL","CANCELLED","Raised in error","Sim Tian Kee","Coach 3","Wei Ming","08:20"),
];

function mk(id, issueType, priority, status, note, delegate, coach, by, raised, vip = false) {
  return { id, issueType, priority, status, isCritical: priority === "CRITICAL",
    note, delegate: delegate ? { name: delegate, vip } : null, coach, raisedBy: by, createdAt: raised };
}

const listeners = new Set();
const emit = (event, payload) => listeners.forEach((fn) => fn(event, payload));
const nowHM = () => new Date().toLocaleTimeString("en-SG", { hour: "2-digit", minute: "2-digit", hour12: false });

function summarise(rows) {
  return {
    all: rows.length,
    critical: rows.filter((t) => t.priority === "CRITICAL").length,
    open: rows.filter((t) => t.status === "OPEN").length,
    resolved: rows.filter((t) => t.status === "RESOLVED").length,
  };
}
const order = { CRITICAL: 0, NORMAL: 1, LOW: 2 };
const sortRows = (rows) => [...rows].sort((a, b) => order[a.priority] - order[b.priority]);

/* ============================== PUBLIC API =============================== */

export async function getDelegates(tripId = TRIP_ID) {
  if (USE_SIMULATION) return DELEGATES;
  const data = await http("GET", `/delegates/${tripId}`);
  return data.items;
}

export async function listExceptions({ status, priority } = {}) {
  if (USE_SIMULATION) {
    await wait(250);
    let rows = SIM;
    if (status) rows = rows.filter((t) => t.status === status);
    if (priority) rows = rows.filter((t) => t.priority === priority);
    return { items: sortRows(rows), summary: summarise(SIM) };
  }
  const q = new URLSearchParams({ tripId: TRIP_ID, ...(status && { status }), ...(priority && { priority }) });
  const data = await http("GET", `/exceptions?${q}`);
  return { items: data.items, summary: data.summary };
}

export async function createException({ issueType, delegateId, note, markCritical }) {
  if (USE_SIMULATION) {
    await wait(400);
    const del = DELEGATES.find((d) => d.id === delegateId) || null;
    const row = mk(`e-${Math.floor(Math.random() * 9000 + 1000)}`, issueType,
      markCritical ? "CRITICAL" : "NORMAL", "OPEN", note || "", del?.name, del?.coach || "—", "You", nowHM(), del?.vip);
    SIM = [row, ...SIM];
    emit(markCritical ? "exception:critical" : "exception:created", row);
    return row;
  }
  return http("POST", "/exceptions", { tripId: TRIP_ID, issueType, delegateId, note, markCritical });
}

export async function resolveException(id, resolutionNote) {
  if (USE_SIMULATION) {
    await wait(250);
    SIM = SIM.map((t) => (t.id === id ? { ...t, status: "RESOLVED" } : t));
    emit("exception:updated", { id, status: "RESOLVED" });
    return SIM.find((t) => t.id === id);
  }
  return http("PATCH", `/exceptions/${id}/resolve`, { resolutionNote });
}

export async function cancelException(id) {
  if (USE_SIMULATION) {
    await wait(250);
    SIM = SIM.map((t) => (t.id === id ? { ...t, status: "CANCELLED" } : t));
    emit("exception:updated", { id, status: "CANCELLED" });
    return { id, status: "CANCELLED" };
  }
  return http("DELETE", `/exceptions/${id}`);
}

/** Subscribe to live ticket events. Returns an unsubscribe function. */
export function subscribeStream(onEvent) {
  if (USE_SIMULATION) {
    listeners.add(onEvent);
    return () => listeners.delete(onEvent);
  }
  const es = new EventSource(`${BASE_URL}/exceptions/stream?tripId=${TRIP_ID}`);
  ["exception:created", "exception:critical", "exception:updated"].forEach((ev) =>
    es.addEventListener(ev, (m) => onEvent(ev, JSON.parse(m.data)))
  );
  return () => es.close();
}

const wait = (ms) => new Promise((r) => setTimeout(r, ms));

