/* Exception Inbox — responsive layer (extends tokens.css). Owner: Jayden. */

.exc-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
.exc-live {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 12px; font-weight: 600; color: var(--st-present);
  background: var(--st-present-bg); padding: 5px 11px; border-radius: 999px;
}
.exc-live .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--st-present); animation: excPulse 1.6s ease-in-out infinite; }
@keyframes excPulse { 0%,100% { opacity: 1; } 50% { opacity: 0.3; } }

/* Critical banner */
.exc-banner {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 16px 20px; margin: 20px 0;
  background: var(--scc-red-tint); border: 1px solid var(--scc-red-tint-2);
  border-left: 4px solid var(--scc-red); border-radius: var(--r-lg);
}
.exc-banner__title { font-weight: 700; color: var(--scc-red-700); }
.exc-banner__sub { color: var(--scc-red-700); font-size: 14px; }

/* Toolbar: tabs + action */
.exc-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 18px; flex-wrap: wrap; }
.exc-tabs { display: flex; gap: 10px; flex-wrap: wrap; }
.exc-tab {
  border: 1px solid var(--line); background: #fff; color: var(--ink-2);
  border-radius: 999px; padding: 8px 16px; font-size: 14px; font-weight: 600;
}
.exc-tab:hover { background: var(--surface-2); }
.exc-tab.active { background: var(--ink); color: #fff; border-color: var(--ink); }
.exc-tab .count { opacity: 0.7; font-variant-numeric: tabular-nums; }
.exc-tab.active .count { opacity: 0.85; }

/* Row action buttons */
.exc-actions { display: flex; gap: 8px; justify-content: flex-end; }
.exc-btn-sm { font-size: 13px; padding: 6px 12px; border-radius: var(--r-sm); border: 1px solid var(--line); background: #fff; font-weight: 600; color: var(--ink-2); }
.exc-btn-sm:hover { background: var(--surface-2); }
.exc-btn-sm.resolve { color: var(--st-present); border-color: var(--st-present-bg); }
.exc-btn-sm.cancel  { color: var(--ink-3); }

/* Desktop table vs mobile cards */
.exc-cards { display: none; }
.exc-issue-title { font-weight: 600; }
.exc-issue-sub { color: var(--ink-3); font-size: 12px; }
.vip-tag { font-size: 10px; font-weight: 700; color: var(--scc-red); background: var(--scc-red-tint); padding: 1px 6px; border-radius: 6px; margin-left: 6px; }

/* States */
.exc-state { text-align: center; padding: 48px 24px; color: var(--ink-3); }
.exc-skeleton { height: 56px; border-radius: var(--r-sm); background: linear-gradient(90deg, var(--line-2) 25%, var(--surface-2) 37%, var(--line-2) 63%); background-size: 400% 100%; animation: excShimmer 1.4s ease infinite; margin: 8px 0; }
@keyframes excShimmer { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }

/* Toast */
.exc-toast {
  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
  background: var(--ink); color: #fff; padding: 12px 20px; border-radius: 999px;
  font-size: 14px; font-weight: 500; box-shadow: var(--shadow-lg); z-index: 60;
}

/* Modal */
.modal-overlay { position: fixed; inset: 0; background: rgba(16,24,40,0.45); display: grid; place-items: center; z-index: 50; padding: 20px; }
.modal {
  width: 100%; max-width: 440px; background: var(--surface);
  border-radius: var(--r-lg); box-shadow: var(--shadow-lg); overflow: hidden;
  max-height: 92vh; display: flex; flex-direction: column;
}
.modal-head { display: flex; align-items: center; justify-content: space-between; padding: 20px 22px 8px; }
.modal-head h2 { font-size: 20px; }
.modal-body { padding: 8px 22px 22px; overflow-y: auto; }
.modal-x { border: none; background: none; color: var(--ink-3); padding: 4px; border-radius: var(--r-sm); }
.modal-x:hover { background: var(--surface-2); }

.issue-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 18px; }
.issue-opt {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  padding: 14px 8px; border: 1px solid var(--line); border-radius: var(--r-md);
  background: #fff; font-size: 13px; font-weight: 600; color: var(--ink-2);
}
.issue-opt:hover { border-color: var(--ink-3); }
.issue-opt.selected { border-color: var(--scc-red); background: var(--scc-red-tint); color: var(--scc-red-700); }

.critical-toggle {
  display: flex; align-items: center; gap: 12px; padding: 12px 14px;
  border: 1px solid var(--scc-red-tint-2); background: var(--scc-red-tint);
  border-radius: var(--r-md); margin: 16px 0; cursor: pointer;
}
.switch { width: 40px; height: 24px; border-radius: 999px; background: var(--line); position: relative; flex-shrink: 0; transition: background 0.15s; }
.switch.on { background: var(--scc-red); }
.switch .knob { position: absolute; top: 3px; left: 3px; width: 18px; height: 18px; border-radius: 50%; background: #fff; transition: transform 0.15s; }
.switch.on .knob { transform: translateX(16px); }

textarea.input { resize: vertical; min-height: 64px; }

/* focus visibility (accessibility floor) */
.exc-tab:focus-visible, .exc-btn-sm:focus-visible, .issue-opt:focus-visible, .modal-x:focus-visible { outline: 2px solid var(--scc-red); outline-offset: 2px; }

/* ---------------------- Phone view (<= 720px) ------------------------- */
@media (max-width: 720px) {
  .exc-table-wrap { display: none; }          /* hide the desktop table  */
  .exc-cards { display: block; }               /* show stacked cards      */
  .exc-toolbar { flex-direction: column; align-items: stretch; }
  .exc-toolbar .btn-primary { width: 100%; }
  .exc-tabs { overflow-x: auto; flex-wrap: nowrap; padding-bottom: 4px; -webkit-overflow-scrolling: touch; }
  .exc-tab { white-space: nowrap; }
  .exc-banner { flex-direction: column; align-items: flex-start; }
  .exc-banner .btn { width: 100%; }

  .exc-card { padding: 14px 16px; border-bottom: 1px solid var(--line-2); }
  .exc-card:last-child { border-bottom: none; }
  .exc-card__top { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 8px; }
  .exc-card__meta { color: var(--ink-3); font-size: 13px; margin: 2px 0; }
  .exc-card .exc-actions { margin-top: 12px; }
  .exc-card .exc-btn-sm { flex: 1; text-align: center; }

  /* modal becomes a bottom sheet */
  .modal-overlay { align-items: flex-end; padding: 0; }
  .modal { max-width: 100%; border-radius: var(--r-lg) var(--r-lg) 0 0; max-height: 94vh; }
  .issue-grid { grid-template-columns: 1fr 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  .exc-live .dot, .exc-skeleton { animation: none; }
  .switch, .switch .knob { transition: none; }
}

