import { X, UserX, BadgeX, BatteryLow, Accessibility } from "lucide-react";
import { getDelegates, createException } from "../lib/exceptionsApi.js";

const ISSUE_TYPES = [
  { value: "MISSING_PERSON",    label: "Missing person", Icon: UserX },
  { value: "LOST_BADGE",        label: "Lost badge",     Icon: BadgeX },
  { value: "DEAD_PHONE",        label: "Dead phone",     Icon: BatteryLow },
  { value: "VIP_REQUEST",       label: "VIP request",    Icon: Accessibility },
];

/**
 * "Log exception" — creates a support ticket (Create in the CRUD set).
 * Enabling "Mark as critical" raises the priority and fans out a live alert.
 */
export default function LogExceptionModal({ onClose, onCreated }) {
  const [delegates, setDelegates] = useState([]);
  const [issueType, setIssueType] = useState("MISSING_PERSON");
  const [delegateId, setDelegateId] = useState("");
  const [note, setNote] = useState("");
  const [critical, setCritical] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    getDelegates().then(setDelegates).catch(() => setDelegates([]));
    const onKey = (e) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  async function submit() {
    if (!issueType) { setError("Choose an issue type."); return; }
    setSaving(true); setError("");
    try {
      const created = await createException({ issueType, delegateId: delegateId || null, note, markCritical: critical });
      onCreated(created, critical);
    } catch (e) {
      setError(e.message || "Could not log the exception. Try again.");
      setSaving(false);
    }
  }

  return (
    <div className="modal-overlay" onClick={onClose} role="dialog" aria-modal="true" aria-label="Log exception">
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <h2>Log exception</h2>
          <button className="modal-x" onClick={onClose} aria-label="Close"><X size={20} /></button>
        </div>
        <div className="modal-body">
          <label className="field-label">Issue type</label>
          <div className="issue-grid">
            {ISSUE_TYPES.map(({ value, label, Icon }) => (
              <button
                key={value}
                type="button"
                className={"issue-opt" + (issueType === value ? " selected" : "")}
                onClick={() => setIssueType(value)}
                aria-pressed={issueType === value}
              >
                <Icon size={20} strokeWidth={2} />
                {label}
              </button>
            ))}
          </div>

          <label className="field-label">Delegate</label>
          <select className="select" value={delegateId} onChange={(e) => setDelegateId(e.target.value)} style={{ marginBottom: 16 }}>
            <option value="">Unidentified / not listed</option>
            {delegates.map((d) => (
              <option key={d.id} value={d.id}>{d.name} · {d.coach}{d.vip ? " · VIP" : ""}</option>
            ))}
          </select>

          <label className="field-label">Quick note</label>
          <textarea
            className="input"
            placeholder="e.g. Phone unreachable. Last seen near gift shop at 14:08."
            value={note}
            onChange={(e) => setNote(e.target.value)}
            style={{ marginBottom: 4 }}
          />

          <div
            className="critical-toggle"
            role="switch"
            aria-checked={critical}
            tabIndex={0}
            onClick={() => setCritical((v) => !v)}
            onKeyDown={(e) => (e.key === " " || e.key === "Enter") && (e.preventDefault(), setCritical((v) => !v))}
          >
            <span className={"switch" + (critical ? " on" : "")}><span className="knob" /></span>
            <div>
              <div style={{ fontWeight: 700, color: "var(--scc-red-700)" }}>Mark as critical</div>
              <div style={{ fontSize: 13, color: "var(--scc-red-700)" }}>Alerts all staff devices instantly</div>
            </div>
          </div>

          {error && <p style={{ color: "var(--scc-red)", fontSize: 13, marginBottom: 8 }}>{error}</p>}

          <button className={"btn btn-block " + (critical ? "btn-primary" : "btn-dark")} onClick={submit} disabled={saving}>
            {saving ? "Submitting…" : critical ? "Submit & alert team" : "Submit ticket"}
          </button>
        </div>
      </div>
    </div>
  );
}
