import { useEffect, useState, useCallback } from "react";
import { AlertTriangle, Plus } from "lucide-react";
import StatusBadge from "../components/StatusBadge.jsx";
import LogExceptionModal from "../components/LogExceptionModal.jsx";
import {
  listExceptions, resolveException, cancelException, subscribeStream, USE_SIMULATION,
} from "../lib/exceptionsApi.js";
import "./ExceptionInboxPage.css";

const TABS = [
  { key: "All",      filter: {} },
  { key: "Critical", filter: { priority: "CRITICAL" } },
  { key: "Open",     filter: { status: "OPEN" } },
  { key: "Resolved", filter: { status: "RESOLVED" } },
];

const ISSUE_LABEL = {
  MISSING_PERSON: "Missing person", LOST_BADGE: "Lost badge",
  FACE_MATCH_FAILED: "Face match failed", DEAD_PHONE: "Dead phone",
  VIP_REQUEST: "VIP request", OTHER: "Other",
};

/**
 * Exception Inbox / Support Tickets — Jayden (Screen 5).
 * Full CRUD read/triage view: filter, log (create), resolve (update),
 * cancel (soft delete), with a live critical-alert banner over SSE.
 * Responsive: table on desktop, stacked cards on phones.
 */
export default function ExceptionInboxPage() {
  const [tab, setTab] = useState("All");
  const [items, setItems] = useState([]);
  const [summary, setSummary] = useState({ all: 0, critical: 0, open: 0, resolved: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [modalOpen, setModalOpen] = useState(false);
  const [toast, setToast] = useState("");

  const activeFilter = TABS.find((t) => t.key === tab).filter;

  const load = useCallback(async () => {
    setLoading(true); setError("");
    try {
      const { items, summary } = await listExceptions(activeFilter);
      setItems(items); setSummary(summary);
    } catch (e) {
      setError("Couldn't load tickets. Check the connection and try again.");
    } finally {
      setLoading(false);
    }
  }, [tab]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => { load(); }, [load]);

  // Live updates: refresh the list whenever a ticket changes anywhere.
  useEffect(() => {
    const unsub = subscribeStream((event) => {
      load();
      if (event === "exception:critical") flash("Critical alert pushed to all staff devices");
    });
    return unsub;
  }, [load]);

  function flash(msg) { setToast(msg); setTimeout(() => setToast(""), 2600); }

  async function handleResolve(id) {
    await resolveException(id, "Resolved from inbox");
    flash("Ticket resolved");
  }
  async function handleCancel(id) {
    await cancelException(id);
    flash("Ticket cancelled");
  }
  function handleCreated(_row, wasCritical) {
    setModalOpen(false);
    flash(wasCritical ? "Critical alert pushed to all staff devices" : "Exception logged");
  }

  const critical = items.find((t) => t.priority === "CRITICAL" && t.status === "OPEN")
    || (tab !== "All" && summary.critical > 0 ? { fromSummary: true } : null);

  return (
    <div className="page">
      <div className="exc-header">
        <div>
          <div className="page-eyebrow">Beijing study mission · Day 3</div>
          <h1 className="page-title">Exceptions</h1>
          <p className="page-sub">On-ground support tickets across all coaches and venues</p>
        </div>
        <span className="exc-live"><span className="dot" /> Live{USE_SIMULATION ? " · demo data" : ""}</span>
      </div>

      {critical && !critical.fromSummary && (
        <div className="exc-banner">
          <div className="row" style={{ alignItems: "flex-start" }}>
            <AlertTriangle size={22} color="var(--scc-red)" strokeWidth={2.2} />
            <div>
              <div className="exc-banner__title">1 critical exception · pushed to all 5 staff devices</div>
              <div className="exc-banner__sub">
                {ISSUE_LABEL[critical.issueType]} · {critical.coach || "—"} · {critical.delegate?.name || "Unidentified"} · created {fmt(critical.createdAt)}
              </div>
            </div>
          </div>
          <button className="btn btn-primary" onClick={() => handleResolve(critical.id)}>Resolve now</button>
        </div>
      )}

      <div className="exc-toolbar">
        <div className="exc-tabs" role="tablist">
          {TABS.map(({ key }) => (
            <button
              key={key}
              role="tab"
              aria-selected={tab === key}
              className={"exc-tab" + (tab === key ? " active" : "")}
              onClick={() => setTab(key)}
            >
              {key} <span className="count">· {summary[key.toLowerCase()] ?? 0}</span>
            </button>
          ))}
        </div>
        <button className="btn btn-primary" onClick={() => setModalOpen(true)}>
          <Plus size={16} strokeWidth={2.5} /> Log exception
        </button>
      </div>

      {/* ----- Desktop table ----- */}
      <div className="card exc-table-wrap" style={{ padding: 4 }}>
        <table className="table">
          <thead>
            <tr><th>Priority</th><th>Issue</th><th>Delegate</th><th>Coach</th><th>Raised</th><th>Status</th><th></th></tr>
          </thead>
          <tbody>
            {loading && Array.from({ length: 4 }).map((_, i) => (
              <tr key={i}><td colSpan={7}><div className="exc-skeleton" /></td></tr>
            ))}
            {!loading && items.map((t) => (
              <tr key={t.id}>
                <td><StatusBadge state={t.priority} /></td>
                <td>
                  <div className="exc-issue-title">
                    {ISSUE_LABEL[t.issueType]}
                    {t.delegate?.vip && <span className="vip-tag">VIP</span>}
                  </div>
                  <div className="exc-issue-sub">{t.note}</div>
                </td>
                <td>{t.delegate?.name || "Unidentified"}</td>
                <td className="mono">{t.coach || "—"}</td>
                <td className="muted">{fmt(t.createdAt)} · {t.raisedBy}</td>
                <td><StatusBadge state={t.status}>{t.status === "CANCELLED" ? "Cancelled" : undefined}</StatusBadge></td>
                <td>
                  {t.status === "OPEN" && (
                    <div className="exc-actions">
                      <button className="exc-btn-sm resolve" onClick={() => handleResolve(t.id)}>Resolve</button>
                      <button className="exc-btn-sm cancel" onClick={() => handleCancel(t.id)}>Cancel</button>
                    </div>
                  )}
                </td>
              </tr>
            ))}
            {!loading && !error && items.length === 0 && (
              <tr><td colSpan={7}><div className="exc-state">All clear — no tickets in this view.</div></td></tr>
            )}
            {error && <tr><td colSpan={7}><div className="exc-state">{error} <button className="exc-btn-sm" onClick={load} style={{ marginLeft: 8 }}>Retry</button></div></td></tr>}
          </tbody>
        </table>
      </div>

      {/* ----- Mobile cards ----- */}
      <div className="card exc-cards">
        {loading && Array.from({ length: 3 }).map((_, i) => <div key={i} className="exc-card"><div className="exc-skeleton" /></div>)}
        {!loading && items.map((t) => (
          <div className="exc-card" key={t.id}>
            <div className="exc-card__top">
              <StatusBadge state={t.priority} />
              <StatusBadge state={t.status}>{t.status === "CANCELLED" ? "Cancelled" : undefined}</StatusBadge>
            </div>
            <div className="exc-issue-title">
              {ISSUE_LABEL[t.issueType]}{t.delegate?.vip && <span className="vip-tag">VIP</span>}
            </div>
            <div className="exc-issue-sub">{t.note}</div>
            <div className="exc-card__meta">{t.delegate?.name || "Unidentified"} · {t.coach || "—"}</div>
            <div className="exc-card__meta">{fmt(t.createdAt)} · {t.raisedBy}</div>
            {t.status === "OPEN" && (
              <div className="exc-actions">
                <button className="exc-btn-sm resolve" onClick={() => handleResolve(t.id)}>Resolve</button>
                <button className="exc-btn-sm cancel" onClick={() => handleCancel(t.id)}>Cancel</button>
              </div>
            )}
          </div>
        ))}
        {!loading && !error && items.length === 0 && <div className="exc-state">All clear — no tickets in this view.</div>}
        {error && <div className="exc-state">{error} <button className="exc-btn-sm" onClick={load}>Retry</button></div>}
      </div>

      {modalOpen && <LogExceptionModal onClose={() => setModalOpen(false)} onCreated={handleCreated} />}
      {toast && <div className="exc-toast">{toast}</div>}
    </div>
  );
}

/** DB returns ISO datetimes; sim returns "HH:MM". Normalise to HH:MM. */
function fmt(v) {
  if (!v) return "";
  if (/^\d{2}:\d{2}$/.test(v)) return v;
  const d = new Date(v.replace(" ", "T"));
  return isNaN(d) ? v : d.toLocaleTimeString("en-SG", { hour: "2-digit", minute: "2-digit", hour12: false });
}
