import { Routes, Route, Navigate } from "react-router-dom";
import Layout from "./components/Layout.jsx";
import ExceptionInboxPage from "./pages/ExceptionInboxPage.jsx";

/**
 * Standalone build — Exception Logging feature only (Jayden).
 *
 * No login and no teammate routes: the app opens straight into the Exception
 * Inbox inside the shared admin shell. The sidebar is kept for design
 * continuity but its links are inert (this build has a single view).
 */
export default function App() {
  return (
    <Routes>
      <Route element={<Layout />}>
        <Route path="/exceptions" element={<ExceptionInboxPage />} />
        <Route path="*" element={<Navigate to="/exceptions" replace />} />
      </Route>
    </Routes>
  );
}

