import {
  LayoutGrid,
  MapPin,
  FileText,
  AlertTriangle,
  MessageSquare,
  ClipboardCheck,
} from "lucide-react";

/**
 * Left navigation rail. Design is unchanged from the full app, but in this
 * standalone build the items are non-interactive — only the Exceptions view
 * exists — so they render as static labels with Exceptions marked active.
 * `exceptionCount` drives the red pill on the Exceptions item.
 */
export default function Sidebar({ exceptionCount = 0 }) {
  const items = [
    { label: "Dashboard", icon: LayoutGrid },
    { label: "Trips", icon: MapPin },
    { label: "Documents", icon: FileText },
    { label: "Exceptions", icon: AlertTriangle, badge: exceptionCount, active: true },
    { label: "Chat assistant", icon: MessageSquare },
  ];

  return (
    <nav className="sidebar" aria-label="Primary">
      <div className="sidebar-brand wordmark">
        <ClipboardCheck size={22} strokeWidth={2.4} /> MusterGo
      </div>
      {items.map(({ label, icon: Icon, badge, active }) => (
        <div
          key={label}
          className={"nav-item" + (active ? " active" : "")}
          aria-current={active ? "page" : undefined}
        >
          <Icon size={18} strokeWidth={2} />
          {label}
          {badge ? <span className="nav-badge">{badge}</span> : null}
        </div>
      ))}
    </nav>
  );
}

