import pg from "pg";
import "dotenv/config";

const { Pool } = pg;

/**
 * Shared PostgreSQL pool (Neon). Postgres is the only database for the project.
 *
 * Neon gives you a single connection string — put it in .env as DATABASE_URL,
 * e.g. postgresql://user:pass@ep-xxx.ap-southeast-1.aws.neon.tech/mustergo?sslmode=require
 * If DATABASE_URL is absent, falls back to discrete DB_* vars for local Postgres.
 */
