import jwt from "jsonwebtoken";
import { q } from "../db/pool.js";

const SECRET = process.env.JWT_SECRET || "dev-secret-change-me";

/**
 * Shared auth (owned by the team, stubbed here so the module runs standalone).
 * POST /api/auth/login — demo issues a JWT for any seeded user by email.
 * In the integrated build this is replaced by the teammate's auth service; only
 * requireAuth (token verification) stays on this side.
 */
export async function login(req, res) {
  const { email } = req.body || {};
  const { rows } = await q("SELECT id, name, role FROM users WHERE email = $1 LIMIT 1", [email]);
  if (!rows.length) {
    return res.status(401).json({ error: "INVALID_CREDENTIALS", message: "Incorrect email or password" });
  }
  const user = rows[0];
  const token = jwt.sign({ sub: user.id, role: user.role, name: user.name }, SECRET, { expiresIn: "12h" });
  return res.json({ token, role: user.role, name: user.name, userId: user.id });
}

/** Verify the Bearer JWT and attach req.user. */
export function requireAuth(req, res, next) {
  const header = req.headers.authorization || "";
  const token = header.startsWith("Bearer ") ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: "UNAUTHENTICATED", message: "Missing bearer token" });
  try {
    req.user = jwt.verify(token, SECRET);
    next();
  } catch {
    return res.status(401).json({ error: "UNAUTHENTICATED", message: "Invalid or expired token" });
  }
}
