         (id, trip_id, delegate_id, coach_id, issue_type, priority, status, is_critical, note, raised_by, client_ref)
       VALUES ($1,$2,$3,$4,$5,$6,'OPEN',$7,$8,$9,$10)`,
      [id, tripId, delegateId || null, coach, issueType, priority, !!markCritical, note || null, raisedBy, ref]
    );

    let recipients = 0;
    if (markCritical) {
      const staff = await q("SELECT id FROM users WHERE role IN ('staff','admin')");
      for (const u of staff.rows) {
        await q(
          "INSERT INTO exception_alerts (id, exception_id, recipient_id) VALUES ($1,$2,$3) ON CONFLICT DO NOTHING",
          [randomUUID(), id, u.id]
        );
      }
      recipients = staff.rows.length;
    }

    const { rows } = await q(`${BASE_SELECT} WHERE e.id = $1`, [id]);
    const created = shape(rows[0]);
    broadcast(markCritical ? "exception:critical" : "exception:created", { ...created, recipients });
    res.status(201).json({ ...created, alertDispatched: !!markCritical, recipients });
  } catch (e) { next(e); }
});

/** PATCH /api/exceptions/:id — update priority/note/delegate/coach. */
router.patch("/:id", async (req, res, next) => {
  try {
    const sets = [];
    const params = [];
    const set = (col, val) => { params.push(val); sets.push(`${col} = $${params.length}`); };
    if (req.body.priority !== undefined) { set("priority", req.body.priority); set("is_critical", req.body.priority === "CRITICAL"); }
    if (req.body.note !== undefined)       set("note", req.body.note);
    if (req.body.delegateId !== undefined) set("delegate_id", req.body.delegateId);
    if (req.body.coachId !== undefined)    set("coach_id", req.body.coachId);
    if (!sets.length) return res.status(422).json({ error: "VALIDATION_ERROR", message: "No updatable fields" });
    sets.push(`updated_at = now()`);
    params.push(req.params.id);

    const upd = await q(`UPDATE exceptions SET ${sets.join(", ")} WHERE id = $${params.length} AND status = 'OPEN'`, params);
    if (!upd.rowCount) return res.status(409).json({ error: "CONFLICT", message: "Ticket not open or not found" });

    const { rows } = await q(`${BASE_SELECT} WHERE e.id = $1`, [req.params.id]);
    broadcast("exception:updated", shape(rows[0]));
    res.json(shape(rows[0]));
  } catch (e) { next(e); }
});

/** PATCH /api/exceptions/:id/resolve — resolve with concurrency guard. */
router.patch("/:id/resolve", async (req, res, next) => {
  try {
    const resolvedBy = req.user?.sub || "u-admin";
    const upd = await q(
      `UPDATE exceptions
         SET status='RESOLVED', resolved_at=now(), updated_at=now(), resolved_by=$1, resolution_note=$2
       WHERE id=$3 AND status='OPEN'`,
      [resolvedBy, req.body?.resolutionNote || null, req.params.id]
    );
    if (!upd.rowCount) return res.status(409).json({ error: "ALREADY_RESOLVED", message: "Ticket already resolved or not found" });
    const { rows } = await q(`${BASE_SELECT} WHERE e.id = $1`, [req.params.id]);
    broadcast("exception:updated", shape(rows[0]));
    res.json(shape(rows[0]));
  } catch (e) { next(e); }
});

/** PATCH /api/exceptions/:id/ack — acknowledge a critical alert (Screen 11). */
router.patch("/:id/ack", async (req, res, next) => {
  try {
    const recipient = req.user?.sub || "u-admin";
    const status = req.body?.status === "ON_IT" ? "ON_IT" : "ACKNOWLEDGED";
    const upd = await q(
      `UPDATE exception_alerts
         SET ack_status=$1, acknowledged_at=now()
       WHERE exception_id=$2 AND recipient_id=$3`,
      [status, req.params.id, recipient]
    );
    // If this staffer wasn't in the original fan-out, record their ack anyway.
    if (!upd.rowCount) {
      await q(
        "INSERT INTO exception_alerts (id, exception_id, recipient_id, ack_status, acknowledged_at) VALUES ($1,$2,$3,$4,now()) ON CONFLICT (exception_id, recipient_id) DO UPDATE SET ack_status=$4, acknowledged_at=now()",
        [randomUUID(), req.params.id, recipient, status]
      );
    }
    const counts = await q(
      `SELECT ack_status, COUNT(*)::int AS n FROM exception_alerts WHERE exception_id=$1 GROUP BY ack_status`,
      [req.params.id]
    );
    broadcast("alert:ack", { exceptionId: req.params.id, by: recipient, status });
    res.json({ exceptionId: req.params.id, status, breakdown: counts.rows });
  } catch (e) { next(e); }
});

/** DELETE /api/exceptions/:id — soft delete (cancel). */
router.delete("/:id", async (req, res, next) => {
  try {
    const upd = await q(
      "UPDATE exceptions SET status='CANCELLED', deleted_at=now(), updated_at=now() WHERE id=$1 AND deleted_at IS NULL",
      [req.params.id]
    );
    if (!upd.rowCount) return res.status(404).json({ error: "NOT_FOUND", message: "Ticket not found" });
    broadcast("exception:updated", { id: req.params.id, status: "CANCELLED" });
    res.json({ id: req.params.id, status: "CANCELLED" });
  } catch (e) { next(e); }
});

export default router;
EOF
