import { Router } from "express";
import { randomUUID } from "crypto";
import { q } from "../db/pool.js";
import { requireAuth } from "./auth.js";
import { broadcast } from "./sse.js";

const router = Router();
router.use(requireAuth);

/**
 * POST /api/attendance/scan — mark a delegate PRESENT from a QR/face scan.
 *
 * This mirrors the shared scan endpoint (owned by Vimal in the integrated build).
 * My QR scanner decodes the badge client-side and calls this; an unknown badge
 * returns 404 SCAN_FAILED so the client can route the staffer to Log Exception.
 */
router.post("/scan", async (req, res, next) => {
  try {
    const { tripId, delegateId, method } = req.body || {};
    if (!tripId || !delegateId) {
      return res.status(422).json({ error: "VALIDATION_ERROR", message: "tripId and delegateId are required" });
    }
    const del = await q(
      `SELECT d.id, d.name, d.is_vip, c.label AS coach
         FROM delegates d LEFT JOIN coaches c ON c.id = d.coach_id
        WHERE d.id = $1 AND d.trip_id = $2`,
      [delegateId, tripId]
    );
    if (!del.rows.length) {
      return res.status(404).json({ error: "SCAN_FAILED", message: "Badge not recognised for this trip" });
    }
    const d = del.rows[0];
    const markedBy = req.user?.sub || "u-admin";
    const m = ["QR", "FACE", "MANUAL"].includes(method) ? method : "QR";

    // Upsert: re-scanning the same delegate is idempotent.
    const already = await q("SELECT id FROM attendance WHERE trip_id=$1 AND delegate_id=$2", [tripId, delegateId]);
    if (already.rows.length) {
      return res.json({ status: "ALREADY_PRESENT", delegate: { id: d.id, name: d.name, vip: !!d.is_vip, coach: d.coach } });
    }
    await q(
      "INSERT INTO attendance (id, trip_id, delegate_id, method, status, marked_by) VALUES ($1,$2,$3,$4,'PRESENT',$5)",
      [randomUUID(), tripId, delegateId, m, markedBy]
    );
    broadcast("attendance:checkin", { delegateId, name: d.name, coach: d.coach, method: m });
    res.status(201).json({ status: "CHECKED_IN", delegate: { id: d.id, name: d.name, vip: !!d.is_vip, coach: d.coach } });
  } catch (e) { next(e); }
});

/** PATCH /api/attendance/manual-override — manually set present/absent. */
router.patch("/manual-override", async (req, res, next) => {
  try {
    const { tripId, delegateId, status } = req.body || {};
    if (!tripId || !delegateId) return res.status(422).json({ error: "VALIDATION_ERROR", message: "tripId and delegateId required" });
    const st = status === "ABSENT" ? "ABSENT" : "PRESENT";
    const markedBy = req.user?.sub || "u-admin";
    await q(
      `INSERT INTO attendance (id, trip_id, delegate_id, method, status, marked_by)
       VALUES ($1,$2,$3,'MANUAL',$4,$5)
       ON CONFLICT (trip_id, delegate_id)
       DO UPDATE SET status=$4, method='MANUAL', marked_by=$5, created_at=now()`,
      [randomUUID(), tripId, delegateId, st, markedBy]
    );
    broadcast("attendance:override", { delegateId, status: st });
    res.json({ delegateId, status: st, method: "MANUAL" });
  } catch (e) { next(e); }
});

/** GET /api/attendance/:tripId — head-count summary. */
router.get("/:tripId", async (req, res, next) => {
  try {
    const total = await q("SELECT COUNT(*)::int AS n FROM delegates WHERE trip_id=$1", [req.params.tripId]);
    const present = await q("SELECT COUNT(*)::int AS n FROM attendance WHERE trip_id=$1 AND status='PRESENT'", [req.params.tripId]);
    res.json({ tripId: req.params.tripId, total: total.rows[0].n, present: present.rows[0].n, missing: total.rows[0].n - present.rows[0].n });
  } catch (e) { next(e); }
});

export default router;
EOF
