import express from "express";
import cors from "cors";
import "dotenv/config";
import { q, ping } from "../db/pool.js";
import { login, requireAuth } from "./auth.js";
import { sseHandler } from "./sse.js";
import exceptionsRouter from "./exceptions.routes.js";
import attendanceRouter from "./attendance.routes.js";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/api/health", async (_req, res) => {
  try { await ping(); res.json({ ok: true, db: "postgres" }); }
  catch { res.status(503).json({ ok: false, db: "unreachable" }); }
});
app.post("/api/auth/login", login);

// Real-time stream (SSE) — both apps subscribe here.
app.get("/api/exceptions/stream", sseHandler);

// Delegate lookup for the Log Exception forms (reads the shared delegates table).
app.get("/api/delegates/:tripId", requireAuth, async (req, res, next) => {
  try {
    const { rows } = await q(
      `SELECT d.id, d.name, d.coach_id AS "coachId", c.label AS coach, d.is_vip AS vip
         FROM delegates d LEFT JOIN coaches c ON c.id = d.coach_id
        WHERE d.trip_id = $1 ORDER BY d.name`,
      [req.params.tripId]
    );
    res.json({ items: rows.map((r) => ({ ...r, vip: !!r.vip })) });
  } catch (e) { next(e); }
});

app.use("/api/exceptions", exceptionsRouter);
app.use("/api/attendance", attendanceRouter);

app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: "SERVER_ERROR", message: "Unexpected server error" });
});

const PORT = Number(process.env.PORT || 4000);
app.listen(PORT, () => console.log(`MusterGo API on :${PORT} (PostgreSQL)`));
EOF
