cat > /home/claude/mustergo-project/onground-app/src/lib/exceptionsApi.js << 'APIEOF'
/**
 * On-ground data layer (Jayden). Same shape as the admin app's, tuned for the
 * staff phone: QR check-in, log exception, and live critical alerts.
 *
 * USE_SIMULATION = true  → self-contained demo (no backend).
 * USE_SIMULATION = false → talks to the shared Neon-backed API, so a log raised
 *                          here appears on the admin inbox and alerts fan out to
 *                          every connected phone.
 */
const BASE_URL = import.meta.env.VITE_API_URL || "/api";
export const USE_SIMULATION = true; // flip to false to connect to the shared server
export const TRIP_ID = "trip-bj";
export const CURRENT_USER = { id: "u-admin", name: "Su Lin Wen", role: "admin" };

function authHeader() {
  const token = sessionStorage.getItem("mg_token");
  return token ? { Authorization: `Bearer ${token}` } : {};
}
async function http(method, path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method,
    headers: { "Content-Type": "application/json", ...authHeader() },
    body: body ? JSON.stringify(body) : undefined,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) { const e = new Error(data.message || `${method} ${path} (${res.status})`); e.code = data.error; e.status = res.status; throw e; }
  return data;
}
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const nowHM = () => new Date().toLocaleTimeString("en-SG", { hour: "2-digit", minute: "2-digit", hour12: false });

/* ============================ SIMULATION STORE ============================ */
const DELEGATES = [
  { id: "d-lim",  name: "Lim Wei Jie",   coach: "Coach 2", vip: true },
  { id: "d-tan",  name: "Tan Boon Keng", coach: "Coach 1", vip: false },
  { id: "d-goh",  name: "Goh Mei Ling",  coach: "Coach 2", vip: false },
  { id: "d-chen", name: "Chen Hao Ming", coach: "Coach 2", vip: false },
  { id: "d-yeo",  name: "Yeo Pei Lin",   coach: "Coach 3", vip: false },
  { id: "d-ng",   name: "Ng Soo Peng",   coach: "Coach 1", vip: false },
  { id: "d-wong", name: "Wong Pei Shan", coach: "Coach 2", vip: false },
  { id: "d-sim",  name: "Sim Tian Kee",  coach: "Coach 3", vip: false },
];
const checkedIn = new Set(["d-chen", "d-ng", "d-wong"]);

// Seed the standing critical alert shown on the home screen (matches Screen 11).
let ALERTS = [
  {
    id: "e-999", issueType: "MISSING_PERSON", coach: "Coach 2",
    delegate: { name: "Lim Wei Jie", vip: true },
    note: "Lim Wei Jie (VIP) has not boarded. Last seen near gift shop at 14:08. Departure in 4 min.",
    raisedBy: "Wei Ming", createdAt: "14:18", recipients: 5, myAck: null,
  },
];
const listeners = new Set();
const emit = (event, payload) => listeners.forEach((fn) => fn(event, payload));

/* ============================== PUBLIC API =============================== */

export async function getDelegates() {
  if (USE_SIMULATION) return DELEGATES;
  const d = await http("GET", `/delegates/${TRIP_ID}`);
  return d.items;
}

/** Head-count for the Scan screen. */
export async function getHeadcount() {
  if (USE_SIMULATION) return { total: DELEGATES.length, present: checkedIn.size, missing: DELEGATES.length - checkedIn.size };
  return http("GET", `/attendance/${TRIP_ID}`);
}

/**
 * Check a delegate in from a decoded QR badge.
 * Throws an error with .code = 'SCAN_FAILED' for an unrecognized/damaged badge.
 */
export async function scanCheckin(delegateId, method = "QR") {
  if (USE_SIMULATION) {
    await wait(250);
    const del = DELEGATES.find((d) => d.id === delegateId);
    if (!del) { const e = new Error("Badge not recognised"); e.code = "SCAN_FAILED"; throw e; }
    const already = checkedIn.has(delegateId);
    checkedIn.add(delegateId);
    emit("attendance:checkin", { delegateId, name: del.name });
    return { status: already ? "ALREADY_PRESENT" : "CHECKED_IN", delegate: del };
  }
  const r = await http("POST", "/attendance/scan", { tripId: TRIP_ID, delegateId, method });
  return r;
}

export async function getActiveAlerts() {
  if (USE_SIMULATION) { await wait(150); return ALERTS.filter((a) => a.status !== "RESOLVED"); }
  const d = await http("GET", `/exceptions/active?tripId=${TRIP_ID}`);
  return d.items.filter((t) => t.isCritical).map((t) => ({
    id: t.id, issueType: t.issueType, coach: t.coach, delegate: t.delegate,
    note: t.note, raisedBy: t.raisedBy, createdAt: t.createdAt, recipients: 5, myAck: null,
  }));
}

export async function createException({ issueType, delegateId, note, markCritical }) {
  if (USE_SIMULATION) {
    await wait(400);
    const del = DELEGATES.find((d) => d.id === delegateId) || null;
    const row = {
      id: `e-${Math.floor(Math.random() * 9000 + 1000)}`, issueType, coach: del?.coach || "—",
      delegate: del ? { name: del.name, vip: del.vip } : null, note: note || "",
      raisedBy: CURRENT_USER.name, createdAt: nowHM(), recipients: 5, myAck: null,
    };
    if (markCritical) { ALERTS = [row, ...ALERTS]; emit("exception:critical", row); }
    else emit("exception:created", row);
    return row;
  }
  return http("POST", "/exceptions", { tripId: TRIP_ID, issueType, delegateId, note, markCritical });
}

/** Acknowledge a critical alert. status: 'ACKNOWLEDGED' | 'ON_IT'. */
export async function ackAlert(id, status) {
  if (USE_SIMULATION) {
    await wait(200);
    ALERTS = ALERTS.map((a) => (a.id === id ? { ...a, myAck: status } : a));
    emit("alert:ack", { id, status });
    return { id, status };
  }
  return http("PATCH", `/exceptions/${id}/ack`, { status });
}

/** Subscribe to live events. Returns an unsubscribe function. */
export function subscribeStream(onEvent) {
  if (USE_SIMULATION) { listeners.add(onEvent); return () => listeners.delete(onEvent); }
  const es = new EventSource(`${BASE_URL}/exceptions/stream?tripId=${TRIP_ID}`);
  ["exception:created", "exception:critical", "exception:updated", "alert:ack", "attendance:checkin"].forEach((ev) =>
    es.addEventListener(ev, (m) => onEvent(ev, JSON.parse(m.data)))
  );
  return () => es.close();
}
APIEOF
