/* On-ground staff app — mobile-first shell + screen styles. Owner: Jayden. */

:root { --tabbar-h: 64px; }

body { background: #0d0d0f; }

/* Center a phone-width column on desktop; fill the screen on a real phone. */
.phone {
  max-width: 430px;
  margin: 0 auto;
  min-height: 100vh;
  min-height: 100dvh;
  background: var(--bg);
  position: relative;
  display: flex;
  flex-direction: column;
  box-shadow: 0 0 60px rgba(0,0,0,0.35);
}
.screen { flex: 1; display: flex; flex-direction: column; padding-bottom: var(--tabbar-h); }
.screen-scroll { flex: 1; overflow-y: auto; }

/* ---- Bottom tab bar ---- */
.tabbar {
  position: sticky; bottom: 0; height: var(--tabbar-h);
  display: flex; background: var(--surface); border-top: 1px solid var(--line);
  padding-bottom: env(safe-area-inset-bottom, 0);
}
.tabbar.dark { background: #161618; border-top-color: #26262a; }
.tab {
  flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 3px; font-size: 11px; font-weight: 600; color: var(--ink-3);
  background: none; border: none; text-decoration: none;
}
.tab.dark { color: #8b8b92; }
.tab.active { color: var(--scc-red); }

/* ================= SCAN SCREEN (dark) ================= */
.scan { background: #161618; color: #fff; flex: 1; display: flex; flex-direction: column; }
.scan-top { display: flex; align-items: center; justify-content: space-between; padding: 16px 18px; }
.scan-top .title { font-weight: 600; font-size: 15px; }
.scan-top button { background: none; border: none; color: #fff; padding: 4px; }
.scan-stage { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 0 24px; }
.scan-frame {
  width: 260px; height: 260px; border-radius: 24px; position: relative;
  background: #0b0b0c; overflow: hidden; display: grid; place-items: center;
}
.scan-frame video { width: 100%; height: 100%; object-fit: cover; }
.scan-frame .corners { position: absolute; inset: 0; pointer-events: none; }
.scan-frame .corners::before, .scan-frame .corners::after {
  content: ""; position: absolute; width: 44px; height: 44px; border: 3px solid #fff; border-radius: 8px;
}
.scan-frame .corners::before { top: 12px; left: 12px; border-right: none; border-bottom: none; }
.scan-frame .corners::after  { bottom: 12px; right: 12px; border-left: none; border-top: none; }
.scan-laser { position: absolute; left: 12px; right: 12px; height: 2px; background: var(--scc-red); box-shadow: 0 0 12px var(--scc-red); animation: laser 2.2s ease-in-out infinite; }
@keyframes laser { 0%,100% { top: 16px; } 50% { top: calc(100% - 16px); } }
.scan-hint { margin-top: 18px; color: #b9b9c0; font-size: 14px; text-align: center; }

.scan-modes { display: flex; gap: 10px; margin-top: 22px; }
.scan-mode { padding: 9px 20px; border-radius: 999px; border: none; font-weight: 600; font-size: 14px; background: #26262a; color: #d5d5db; }
.scan-mode.active { background: #fff; color: #161618; }

.scan-cant { display: flex; align-items: center; gap: 12px; background: #26262a; border-radius: 999px; padding: 8px 8px 8px 18px; margin: 22px 0 8px; }
.scan-cant span { color: #d5d5db; font-size: 14px; }
.scan-cant button { margin-left: auto; background: #fff; color: #161618; border: none; border-radius: 999px; padding: 9px 16px; font-weight: 600; font-size: 14px; }

/* scan result banners */
.scan-result { position: absolute; left: 16px; right: 16px; bottom: calc(var(--tabbar-h) + 16px); border-radius: var(--r-md); padding: 14px 16px; display: flex; align-items: center; gap: 12px; font-weight: 600; box-shadow: var(--shadow-lg); z-index: 5; }
.scan-result.ok { background: var(--st-present); color: #fff; }
.scan-result.bad { background: var(--scc-red); color: #fff; }
.scan-result .sub { font-weight: 500; font-size: 13px; opacity: 0.92; }

.cam-fallback { text-align: center; color: #b9b9c0; padding: 20px; }
.cam-fallback .btn-demo { margin-top: 14px; background: #fff; color: #161618; border: none; border-radius: var(--r-sm); padding: 10px 16px; font-weight: 600; }

/* ================= LOG EXCEPTION (light) ================= */
.og-page { padding: 20px 18px; }
.og-h1 { font-size: 22px; font-weight: 700; margin-bottom: 18px; }
.og-label { font-size: 12px; font-weight: 700; letter-spacing: 0.06em; color: var(--ink-3); text-transform: uppercase; margin: 18px 0 8px; }
.issue-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.issue-opt { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 16px 8px; border: 1.5px solid var(--line); border-radius: var(--r-md); background: #fff; font-size: 13px; font-weight: 600; color: var(--ink-2); }
.issue-opt.selected { border-color: var(--scc-red); background: var(--scc-red-tint); color: var(--scc-red-700); }
.delegate-select { display: flex; align-items: center; gap: 12px; border: 1.5px solid var(--line); border-radius: var(--r-md); padding: 12px 14px; width: 100%; background: #fff; text-align: left; }
.delegate-avatar { width: 40px; height: 40px; border-radius: 999px; background: var(--scc-red); color: #fff; font-weight: 700; display: grid; place-items: center; font-size: 14px; }
.delegate-name { font-weight: 700; }
.delegate-meta { font-size: 13px; color: var(--ink-3); }
.crit-toggle { display: flex; align-items: center; gap: 12px; padding: 14px; border: 1.5px solid var(--scc-red-tint-2); background: var(--scc-red-tint); border-radius: var(--r-md); margin: 18px 0; width: 100%; }
.switch { width: 44px; height: 26px; border-radius: 999px; background: var(--line); position: relative; flex-shrink: 0; transition: background .15s; }
.switch.on { background: var(--scc-red); }
.switch .knob { position: absolute; top: 3px; left: 3px; width: 20px; height: 20px; border-radius: 50%; background: #fff; transition: transform .15s; }
.switch.on .knob { transform: translateX(18px); }
.btn-submit { width: 100%; border: none; border-radius: var(--r-md); padding: 16px; font-size: 16px; font-weight: 700; color: #fff; background: var(--scc-red); }
.btn-submit.normal { background: var(--ink); }
.btn-submit:disabled { opacity: .6; }

/* ================= HOME / ALERTS ================= */
.home { padding: 22px 18px; }
.home-greet { color: var(--ink-3); font-size: 15px; }
.home-name { font-size: 26px; font-weight: 700; margin-bottom: 18px; }
.alert-card { background: var(--surface); border-radius: var(--r-lg); box-shadow: var(--shadow-md); overflow: hidden; margin-bottom: 16px; }
.alert-card .bar { height: 6px; background: var(--scc-red); }
.alert-body { padding: 18px; }
.alert-tag { display: inline-flex; align-items: center; gap: 8px; color: var(--scc-red); font-weight: 700; font-size: 13px; letter-spacing: .04em; }
.alert-icon { width: 30px; height: 30px; border-radius: 999px; background: var(--scc-red-tint); display: grid; place-items: center; }
.alert-title { font-size: 22px; font-weight: 700; margin: 12px 0 8px; line-height: 1.2; }
.alert-note { color: var(--ink-2); font-size: 15px; line-height: 1.5; }
.alert-reporter { display: flex; align-items: center; gap: 10px; margin: 16px 0; }
.alert-actions { display: flex; gap: 10px; }
.alert-actions button { flex: 1; border-radius: var(--r-sm); padding: 12px; font-weight: 700; font-size: 15px; border: 1.5px solid var(--line); background: #fff; color: var(--ink); }
.alert-actions .onit { background: var(--scc-red); color: #fff; border-color: var(--scc-red); }
.alert-actions .done { background: var(--st-present); color: #fff; border-color: var(--st-present); }
.alert-sent { text-align: center; color: var(--ink-3); font-size: 13px; margin-top: 12px; }
