import { Routes, Route, Navigate } from "react-router-dom";
import TabBar from "./components/TabBar.jsx";
import HomePage from "./pages/HomePage.jsx";
import ScanPage from "./pages/ScanPage.jsx";
import LogExceptionPage from "./pages/LogExceptionPage.jsx";
import IssuesPage from "./pages/IssuesPage.jsx";
import MePage from "./pages/MePage.jsx";

/**
 * On-ground staff app (Jayden). No login gate for the standalone demo — opens
 * on the home screen where critical alerts land. The three graded screens are
 * Home/Alert, Scan, and Log exception; Issues and Me round out the shell.
 */
export default function App() {
  return (
    <div className="phone">
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/scan" element={<ScanPage />} />
        <Route path="/log" element={<LogExceptionPage />} />
        <Route path="/issues" element={<IssuesPage />} />
        <Route path="/me" element={<MePage />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
      <TabBar />
    </div>
  );
}

