import { useNavigate, useLocation } from "react-router-dom";
import { MapPin, ScanLine, TriangleAlert, User } from "lucide-react";

const TABS = [
  { to: "/", label: "Trips", icon: MapPin, match: (p) => p === "/" },
  { to: "/scan", label: "Scan", icon: ScanLine, match: (p) => p === "/scan" },
  { to: "/issues", label: "Issues", icon: TriangleAlert, match: (p) => p === "/issues" || p === "/log" },
  { to: "/me", label: "Me", icon: User, match: (p) => p === "/me" },
];

export default function TabBar() {
  const nav = useNavigate();
  const { pathname } = useLocation();
  const dark = pathname === "/scan";

  return (
    <nav className={"tabbar" + (dark ? " dark" : "")} aria-label="Primary">
      {TABS.map(({ to, label, icon: Icon, match }) => {
        const active = match(pathname);
        return (
          <button
            key={to}
            className={"tab" + (dark ? " dark" : "") + (active ? " active" : "")}
            onClick={() => nav(to)}
            aria-current={active ? "page" : undefined}
          >
            <Icon size={22} strokeWidth={active ? 2.4 : 2} />
            {label}
          </button>
        );
      })}
    </nav>
  );
}

