import { useEffect, useRef, useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { X, Zap, CheckCircle2, AlertTriangle, ScanLine } from "lucide-react";
import jsQR from "jsqr";
import { scanCheckin, getHeadcount, TRIP_ID } from "../lib/exceptionsApi.js";

/**
 * QR check-in (Screen 9). Uses the device camera + jsQR to decode delegate
 * badges. A valid badge marks attendance; an unrecognised or damaged badge
 * raises the "defective" prompt and offers Log exception as the fallback.
 *
 * Badge payload (see /badges): {"t":"mg-checkin","tripId":"trip-bj","delegateId":"d-lim"}
 */
export default function ScanPage() {
  const nav = useNavigate();
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const rafRef = useRef(0);
  const streamRef = useRef(null);
  const lastRef = useRef({ code: null, at: 0 });

  const [mode, setMode] = useState("QR");
  const [camError, setCamError] = useState("");
  const [result, setResult] = useState(null); // { ok, title, sub }
  const [headcount, setHeadcount] = useState(null);

  const showResult = useCallback((r) => {
    setResult(r);
    setTimeout(() => setResult(null), 2600);
  }, []);

  // Validate a decoded string and check the delegate in.
  const handleDecode = useCallback(async (text) => {
    const now = Date.now();
    if (lastRef.current.code === text && now - lastRef.current.at < 3000) return; // debounce
    lastRef.current = { code: text, at: now };

    let payload;
    try { payload = JSON.parse(text); } catch { payload = null; }
    const valid = payload && payload.t === "mg-checkin" && payload.delegateId;
    if (!valid) {
      showResult({ ok: false, title: "Badge not recognised", sub: "QR is damaged or not a MusterGo badge" });
      return;
    }
    try {
      const r = await scanCheckin(payload.delegateId, "QR");
      const name = r.delegate?.name || "Delegate";
      const coach = r.delegate?.coach ? " · " + r.delegate.coach : "";
      showResult({
        ok: true,
        title: r.status === "ALREADY_PRESENT" ? `${name} already checked in` : `${name} checked in`,
        sub: `Marked present${coach}`,
      });
      getHeadcount().then(setHeadcount).catch(() => {});
    } catch (e) {
      if (e.code === "SCAN_FAILED") showResult({ ok: false, title: "Badge not recognised", sub: "Not on this trip — try Manual or Log exception" });
      else showResult({ ok: false, title: "Check-in failed", sub: e.message || "Try again" });
    }
  }, [showResult]);

  // Camera + decode loop
  useEffect(() => {
    let cancelled = false;
    if (mode !== "QR") return;

    async function start() {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "environment" }, audio: false,
        });
        if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return; }
        streamRef.current = stream;
        const video = videoRef.current;
        video.srcObject = stream;
        video.setAttribute("playsinline", "true");
        await video.play();
        tick();
      } catch (e) {
        setCamError(
          e.name === "NotAllowedError"
            ? "Camera permission denied. Enable it in your browser to scan."
            : "No camera available on this device."
        );
      }
    }

    function tick() {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      if (video && canvas && video.readyState === video.HAVE_ENOUGH_DATA) {
        const ctx = canvas.getContext("2d", { willReadFrequently: true });
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const img = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const code = jsQR(img.data, img.width, img.height, { inversionAttempts: "dontInvert" });
        if (code && code.data) handleDecode(code.data);
      }
      rafRef.current = requestAnimationFrame(tick);
    }

    start();
    getHeadcount().then(setHeadcount).catch(() => {});
    return () => {
      cancelled = true;
      cancelAnimationFrame(rafRef.current);
      streamRef.current?.getTracks().forEach((t) => t.stop());
    };
  }, [mode, handleDecode]);

  return (
    <div className="screen scan">
      <div className="scan-top">
        <button onClick={() => nav("/")} aria-label="Close"><X size={22} /></button>
        <div className="title">QR check in · Coach 2{headcount ? `  ·  ${headcount.present}/${headcount.total}` : ""}</div>
        <button aria-label="Torch"><Zap size={20} /></button>
      </div>

      <div className="scan-stage">
        <div className="scan-frame">
          {mode === "QR" && !camError ? (
            <>
              <video ref={videoRef} muted playsInline />
              <div className="corners" />
              <div className="scan-laser" />
            </>
          ) : camError ? (
            <div className="cam-fallback">
              <ScanLine size={40} />
              <p style={{ marginTop: 10 }}>{camError}</p>
              <button className="btn-demo" onClick={() => handleDecode('{"t":"mg-checkin","tripId":"' + TRIP_ID + '","delegateId":"d-lim"}')}>
                Demo scan (valid badge)
              </button>
              <button className="btn-demo" style={{ marginLeft: 8 }} onClick={() => handleDecode("garbled-qr-data")}>
                Demo scan (defective)
              </button>
            </div>
          ) : (
            <div className="cam-fallback"><p>{mode} check-in coming from the shared scan module.</p></div>
          )}
        </div>
        <canvas ref={canvasRef} style={{ display: "none" }} />
        <p className="scan-hint">Hold delegate's badge inside the frame</p>

        <div className="scan-modes">
          {["Face", "QR", "Manual"].map((m) => (
            <button key={m} className={"scan-mode" + (mode === m ? " active" : "")} onClick={() => { setResult(null); setCamError(""); setMode(m); }}>
              {m}
            </button>
          ))}
        </div>

        <div className="scan-cant">
          <span>Can't scan?</span>
          <button onClick={() => nav("/log")}>Log exception</button>
        </div>
      </div>

      {result && (
        <div className={"scan-result " + (result.ok ? "ok" : "bad")}>
          {result.ok ? <CheckCircle2 size={24} /> : <AlertTriangle size={24} />}
          <div>
            <div>{result.title}</div>
            <div className="sub">{result.sub}</div>
          </div>
        </div>
      )}
    </div>
  );
}

