import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { UserX, BadgeX, BatteryLow, Accessibility, ChevronDown } from "lucide-react";
import { getDelegates, createException } from "../lib/exceptionsApi.js";

const ISSUES = [
  { value: "MISSING_PERSON", label: "Missing person", Icon: UserX },
  { value: "LOST_BADGE",     label: "Lost badge",     Icon: BadgeX },
  { value: "DEAD_PHONE",     label: "Dead phone",     Icon: BatteryLow },
  { value: "VIP_REQUEST",    label: "VIP Request",    Icon: Accessibility },
];
const initials = (n) => n.split(" ").map((w) => w[0]).slice(0, 2).join("").toUpperCase();

/** Log exception (Screen 10). Creating a critical log fans an alert to Screen 11. */
export default function LogExceptionPage() {
  const nav = useNavigate();
  const [delegates, setDelegates] = useState([]);
  const [issueType, setIssueType] = useState("MISSING_PERSON");
  const [delegateId, setDelegateId] = useState("d-lim");
  const [pickerOpen, setPickerOpen] = useState(false);
  const [note, setNote] = useState("Phone unreachable. Last seen near gift shop at 14:08.");
  const [critical, setCritical] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => { getDelegates().then(setDelegates).catch(() => setDelegates([])); }, []);
  const selected = delegates.find((d) => d.id === delegateId);

  async function submit() {
    setSaving(true);
    try {
      await createException({ issueType, delegateId, note, markCritical: critical });
      nav("/", { state: { flash: critical ? "Critical alert sent to all staff" : "Exception logged" } });
    } catch {
      setSaving(false);
    }
  }

  return (
    <div className="screen">
      <div className="screen-scroll og-page">
        <div className="og-h1">Log exception</div>

        <div className="og-label">Issue type</div>
        <div className="issue-grid">
          {ISSUES.map(({ value, label, Icon }) => (
            <button key={value} className={"issue-opt" + (issueType === value ? " selected" : "")} onClick={() => setIssueType(value)} aria-pressed={issueType === value}>
              <Icon size={22} /> {label}
            </button>
          ))}
        </div>

        <div className="og-label">Delegate</div>
        <div style={{ position: "relative" }}>
          <button className="delegate-select" onClick={() => setPickerOpen((v) => !v)}>
            {selected ? (
              <>
                <span className="delegate-avatar">{initials(selected.name)}</span>
                <span style={{ flex: 1 }}>
                  <div className="delegate-name">{selected.name}</div>
                  <div className="delegate-meta">{selected.coach}{selected.vip ? " · VIP" : ""}</div>
                </span>
              </>
            ) : (
              <span style={{ flex: 1, color: "var(--ink-3)" }}>Unidentified / not listed</span>
            )}
            <ChevronDown size={20} color="var(--ink-3)" />
          </button>
          {pickerOpen && (
            <div className="card" style={{ position: "absolute", top: "calc(100% + 6px)", left: 0, right: 0, zIndex: 10, maxHeight: 260, overflowY: "auto", padding: 6 }}>
              <button className="nav-item" style={{ width: "100%" }} onClick={() => { setDelegateId(""); setPickerOpen(false); }}>Unidentified / not listed</button>
              {delegates.map((d) => (
                <button key={d.id} className="nav-item" style={{ width: "100%" }} onClick={() => { setDelegateId(d.id); setPickerOpen(false); }}>
                  <span className="delegate-avatar" style={{ width: 30, height: 30, fontSize: 12 }}>{initials(d.name)}</span>
                  {d.name} · {d.coach}{d.vip ? " · VIP" : ""}
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="og-label">Quick note</div>
        <textarea className="input" value={note} onChange={(e) => setNote(e.target.value)} rows={3} placeholder="What happened?" />

        <button className="crit-toggle" role="switch" aria-checked={critical} onClick={() => setCritical((v) => !v)}>
          <span className={"switch" + (critical ? " on" : "")}><span className="knob" /></span>
          <span style={{ textAlign: "left" }}>
            <div style={{ fontWeight: 700, color: "var(--scc-red-700)" }}>Mark as critical</div>
            <div style={{ fontSize: 13, color: "var(--scc-red-700)" }}>Alerts all staff devices instantly</div>
          </span>
        </button>

        <button className={"btn-submit" + (critical ? "" : " normal")} onClick={submit} disabled={saving}>
          {saving ? "Sending…" : critical ? "Submit & alert team" : "Submit exception"}
        </button>
      </div>
    </div>
  );
}

