import { useEffect, useState, useCallback } from "react";
import { useLocation } from "react-router-dom";
import { AlertTriangle, CheckCircle2 } from "lucide-react";
import { getActiveAlerts, ackAlert, subscribeStream, CURRENT_USER } from "../lib/exceptionsApi.js";

const ISSUE_LABEL = {
  MISSING_PERSON: "Missing person", LOST_BADGE: "Lost badge",
  FACE_MATCH_FAILED: "Face match failed", DEAD_PHONE: "Dead phone",
  VIP_REQUEST: "VIP request", OTHER: "Issue",
};
const initials = (n) => (n || "?").split(" ").map((w) => w[0]).slice(0, 2).join("").toUpperCase();
const greeting = () => { const h = new Date().getHours(); return h < 12 ? "Good morning" : h < 18 ? "Good afternoon" : "Good evening"; };
const fmt = (v) => (!v ? "" : /^\d{2}:\d{2}$/.test(v) ? v : new Date(String(v).replace(" ", "T")).toLocaleTimeString("en-SG", { hour: "2-digit", minute: "2-digit", hour12: false }));

/** Home / Trips (Screen 11). Critical alerts land here in real time. */
export default function HomePage() {
  const location = useLocation();
  const [alerts, setAlerts] = useState([]);
  const [toast, setToast] = useState(location.state?.flash || "");

  const load = useCallback(() => { getActiveAlerts().then(setAlerts).catch(() => setAlerts([])); }, []);

  useEffect(() => { load(); }, [load]);
  useEffect(() => {
    const unsub = subscribeStream((event) => {
      if (event === "exception:critical" || event === "alert:ack" || event === "exception:updated") load();
      if (event === "exception:critical") flash("New critical alert");
    });
    return unsub;
  }, [load]);
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(""), 2600); return () => clearTimeout(t); } }, [toast]);

  function flash(m) { setToast(m); }
  async function onAck(id, status) { await ackAlert(id, status); load(); flash(status === "ON_IT" ? "Marked: I'm on it" : "Acknowledged"); }

  return (
    <div className="screen">
      <div className="screen-scroll home">
        <div className="home-greet">{greeting()}</div>
        <div className="home-name">{CURRENT_USER.name}</div>

        {alerts.length === 0 && (
          <div className="home-empty">
            <div className="ok"><CheckCircle2 size={28} /></div>
            No active alerts. You're all caught up.
          </div>
        )}

        {alerts.map((a) => {
          const acked = a.myAck;
          return (
            <div className="alert-card" key={a.id}>
              <div className="bar" />
              <div className="alert-body">
                <div className="alert-tag"><span className="alert-icon"><AlertTriangle size={16} color="var(--scc-red)" /></span> CRITICAL ALERT</div>
                <div className="alert-title">{ISSUE_LABEL[a.issueType]} — {a.coach || "—"}</div>
                <div className="alert-note">{a.note || `${a.delegate?.name || "A delegate"} needs attention.`}</div>

                <div className="alert-reporter">
                  <span className="delegate-avatar">{initials(a.delegate?.name)}</span>
                  <div>
                    <div style={{ fontWeight: 700 }}>{a.delegate?.name || "Unidentified"}</div>
                    <div className="delegate-meta">Reported by {a.raisedBy} · {fmt(a.createdAt)}</div>
                  </div>
                </div>

                {acked ? (
                  <div className="alert-ackd">{acked === "ON_IT" ? "You're on it ✓" : "Acknowledged ✓"}</div>
                ) : (
                  <div className="alert-actions">
                    <button onClick={() => onAck(a.id, "ACKNOWLEDGED")}>Acknowledge</button>
                    <button className="onit" onClick={() => onAck(a.id, "ON_IT")}>I'm on it</button>
                  </div>
                )}
                <div className="alert-sent">Sent to {a.recipients || 5} more staff</div>
              </div>
            </div>
          );
        })}
      </div>
      {toast && <div className="og-toast">{toast}</div>}
    </div>
  );
}

