{"returncode":0,"stdout":"############ backend/server.js ############
/* =============================================================================
 *  OWNED BY:  InsightMetrics (JQ)
 *  PART OF:   MusterGo base — Admin Dashboard, Auth, Accounts & Permissions
 *
 *  TEAMMATES: please DO NOT edit this file. It is part of JQ's foundation that
 *  the rest of the app is built on. Add your OWN feature files instead, and see
 *  OWNERSHIP.md at the project root for what's yours vs. what's off-limits.
 * ============================================================================= */
/**
 * MusterGo backend — Express API for the SCCCI admin dashboard.
 *
 * Run:
 *   npm install
 *   npm run dev        # http://localhost:4000  (needs a local MySQL server)
 *
 * The data layer (data.js) talks to MySQL and is asynchronous, so the route
 * handlers below are async and `await` it. The server only starts listening
 * AFTER the database connection + schema are ready (see the bottom of the file).
 */

import "dotenv/config"; // loads backend/.env into process.env — MUST be first
import express from "express";
import cors from "cors";
import ExcelJS from "exceljs";
import {
  initDb,
  getTrip,
  getDashboard,
  getMissing,
  getDelegates,
  listDelegates,
  getDelegateById,
  createDelegate,
  updateDelegate,
  deleteDelegate,
  deleteAllDelegates,
  getAccountByUsername,
  accountPermissions,
  listAccounts,
  createAccount,
  updateAccount,
  deleteAccount,
} from "./data.js";

const app = express();
const PORT = process.env.PORT || 4000;

// Allow the frontend origin. In production set FRONTEND_URL (e.g. the Vercel URL);
// locally, no origin means "allow all", which is fine for the Vite dev proxy.
app.use(cors({ origin: process.env.FRONTEND_URL || true, credentials: true }));
app.use(express.json());

app.use((req, _res, next) => {
  console.log(`${new Date().toLocaleTimeString()}  ${req.method} ${req.url}`);
  next();
});

// Wrap async handlers so a rejected promise becomes an Express error (500)
// instead of crashing the process.
const wrap = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

/* ---- Health ------------------------------------------------------------- */
app.get("/api/health", (_req, res) => res.json({ ok: true, service: "mustergo-backend" }));

/* ---- Auth --------------------------------------------------------------- *
 * Login validates against the `accounts` table (see data.js). Accounts are
 * managed by users with the "manageAccounts" permission on the Account control
 * page. The seeded first login is staff_194 / password123!.
 *
 * NOTE (production, not this demo): passwords are stored in plaintext and the
 * token is a simple base64 of the username. A real app would hash passwords
 * (bcrypt) and issue a signed JWT.
 * ------------------------------------------------------------------------- */
function makeToken(username) {
  return `demo.${Buffer.from(String(username)).toString("base64")}.token`;
}

/** Resolve the calling account from the Authorization: Bearer token. */
async function accountFromReq(req) {
  const auth = req.headers.authorization || "";
  const m = auth.match(/^Bearer\s+(.+)$/i);
  if (!m) return null;
  const parts = m[1].split(".");
  if (parts.length < 2) return null;
  let username;
  try {
    username = Buffer.from(parts[1], "base64").toString("utf8");
  } catch {
    return null;
  }
  return (await getAccountByUsername(username)) || null;
}

/** Gate a route on a specific permission. */
function requirePermission(perm) {
  return wrap(async (req, res, next) => {
    const acc = await accountFromReq(req);
    if (!acc) return res.status(401).json({ error: "UNAUTHENTICATED", message: "Please sign in again." });
    if (!accountPermissions(acc)[perm]) {
      return res.status(403).json({ error: "FORBIDDEN", message: "You don't have permission for that action." });
    }
    req.account = acc;
    next();
  });
}

app.post("/api/auth/login", wrap(async (req, res) => {
  const { staffId, password } = req.body || {};

