cat > /tmp/verify.mjs << 'EOF'
import pkg from "/home/claude/.npm-global/lib/node_modules/playwright/index.js";
const { chromium } = pkg;
const b = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium-1194/chrome-linux/chrome", args: ["--no-sandbox"] });
const p = await b.newPage({ viewport: { width: 1360, height: 900 } });
const fails = [];
const ok = (c, m) => { console.log((c ? "PASS  " : "FAIL  ") + m); if (!c) fails.push(m); };

await p.goto("http://localhost:5173/", { waitUntil: "networkidle" });
await p.fill('input#staffId, input[name="staffId"], input[type="text"]', "staff_194").catch(()=>{});
const pw = await p.$('input[type="password"]'); if (pw) await pw.fill("password123!");
await p.getByRole("button", { name: "Sign in", exact: true }).click();
await p.waitForTimeout(1500);
ok(p.url().includes("/dashboard"), "login via team auth lands on dashboard");

await p.getByRole("link", { name: /Exceptions/i }).click();
await p.waitForTimeout(1500);

const body = await p.innerText("body");
ok(/Exception inbox/i.test(body), "page title renders");
ok(/Live/.test(body), "SSE live indicator connected");
ok(/critical exception/i.test(body), "critical alert banner present");
ok(/Lim Wei Jie/.test(body), "real delegate name from Postgres");
ok(/Coach 2/.test(body), "coach joined from coaches table");
ok(/Staff 194/.test(body), "raisedBy resolved from accounts table");
ok(/VIP/.test(body), "VIP flag from delegates table");

// tab counts come from the API
const tabs = await p.$$eval(".exc-tab", els => els.map(e => e.innerText.replace(/\s+/g," ").trim()));
console.log("      tabs:", tabs.join(" | "));
ok(tabs.some(t => /^All · 8/.test(t)), "All count = 8 (7 seeded + 1 created via UI)");
ok(tabs.some(t => /^Open/.test(t)), "Open tab present");

// row actions exist
const resolveBtns = await p.$$(".exc-btn-sm.resolve");
ok(resolveBtns.length > 0, `Resolve buttons rendered (${resolveBtns.length})`);
const overrideBtns = await p.$$eval(".exc-btn-sm", els => els.filter(e=>/Override/.test(e.innerText)).length);
ok(overrideBtns > 0, `Manual override buttons rendered (${overrideBtns})`);

// Resolve a ticket for real
const before = await p.$$eval(".exc-btn-sm.resolve", e => e.length);
await p.$$eval(".exc-btn-sm.resolve", els => els[0].click());
await p.waitForTimeout(1800);
const afterBody = await p.innerText("body");
ok(/resolved/i.test(afterBody), "resolve action produced a toast/updated state");
const after = await p.$$eval(".exc-btn-sm.resolve", e => e.length);
ok(after === before - 1, `open tickets decreased after resolve (${before} -> ${after})`);

// Filter tab works against the API
await p.getByRole("tab", { name: /Resolved/ }).click();
await p.waitForTimeout(1200);
const rows = await p.$$eval("tbody tr", r => r.length);
ok(rows >= 5, `Resolved filter returns rows (${rows})`);

// Mobile: table hides, cards show
await p.setViewportSize({ width: 400, height: 880 });
await p.waitForTimeout(600);
const tableVisible = await p.isVisible(".exc-table-wrap");
const cardsVisible = await p.isVisible(".exc-cards");
ok(!tableVisible && cardsVisible, "mobile: table hidden, cards shown");

await b.close();
console.log(fails.length ? `\n${fails.length} FAILED` : "\nALL CHECKS PASSED");
process.exit(fails.length ? 1 : 0);
EOF

