// frontend/src/pages/QRCheckInPage.jsx
// OWNED BY: FaceCheck-Pro (Vimal)
// Feature: Privacy-First Biometric & Multi-Modal Fusion Scanner
// Route:   /checkin  (registered by JQ in App.jsx — not modified here)
