cd /tmp/qrgen
cat > genv.mjs << 'EOF'
import QRCode from "qrcode";
import { PNG } from "pngjs";
import jsQR from "jsqr";
import fs from "fs";
const OUT = "/home/claude/mustergo-vimal/badges"; fs.mkdirSync(OUT, { recursive: true });
const TRIP = "t-1";

// Real delegate IDs come from Vimal's demo-seed / the shared list. We encode a
// delegate id; the scanner looks it up live, so ANY seeded delegate works.
// For predictable demo we use ids the seed reliably creates, plus edge cases.
const badges = [
  ["d-1",  "Valid delegate (checks in)"],
  ["d-2",  "Valid delegate (checks in)"],
  ["d-3",  "Valid delegate (checks in)"],
  ["__present__", "Already-present delegate (idempotent notice)"],  // resolved at runtime
  ["__unknown__", "Unknown delegate id (routes to Log exception)"],
];

function decodePng(p){const png=PNG.sync.read(fs.readFileSync(p));return jsQR(new Uint8ClampedArray(png.data),png.width,png.height,{inversionAttempts:"dontInvert"});}

let pass=0,fail=0;
for (const [id,label] of badges){
  const payload = id.startsWith("__") ? JSON.stringify({t:"mg-checkin",tripId:TRIP,delegateId:id})
                                      : JSON.stringify({t:"mg-checkin",tripId:TRIP,delegateId:id});
  const file=`${OUT}/badge-${id.replace(/_/g,"")}.png`;
  await QRCode.toFile(file,payload,{width:512,margin:2});
  const r=decodePng(file);
  const okDecode = r && r.data===payload;
  const parsed = okDecode? JSON.parse(r.data):null;
  const validShape = parsed && parsed.t==="mg-checkin" && parsed.delegateId;
  console.log(`${validShape?"PASS":"FAIL"}  ${file.split("/").pop().padEnd(22)} -> ${label}`);
  validShape?pass++:fail++;
}
// A genuinely malformed QR (not our format) -> "defective badge"
const bad=`${OUT}/badge-DEFECTIVE.png`;
await QRCode.toFile(bad,"https://example.com/not-a-badge",{width:512,margin:2});
const rb=decodePng(bad); let bp=null; try{bp=JSON.parse(rb.data)}catch{}
const rejected=!(bp&&bp.t==="mg-checkin");
console.log(`${rejected?"PASS":"FAIL"}  badge-DEFECTIVE.png     -> Defective/not-a-badge (shows error, offers Log exception)`);
rejected?pass++:fail++;
console.log(`\n${pass} passed, ${fail} failed`);
EOF
node genv.mjs
echo "--- files ---"; ls -1 /home/claude/mustergo-vimal/badges/

