// frontend/src/pages/checkin/JaydenQrScanner.jsx
// OWNED BY: Jayden — QR-fallback check-in + defective-badge hand-off.
//
// Rendered inside Vimal's Scan view when the mode toggle is on "QR". It is a
// self-contained component so Vimal's QRCheckInPage.jsx only needs a one-line
// call to mount it — none of his face/voice logic is touched.
//
// Badge payload (see /badges): {"t":"mg-checkin","tripId":"t-1","delegateId":"d-1"}
//
// Flow:
//   valid badge      -> checks the delegate in via POST /api/checkins/manual
//                       (Jayden's own merged endpoint; records method MANUAL,
//                        the honest label for a QR-fallback confirmation) and
//                       calls onCheckedIn() so Vimal's headcount refreshes.
//   already present  -> shows an idempotent "already checked in" notice.
//   unknown / bad QR -> shows the defective-badge error and offers "Log
//                       exception", which calls onLogException() to jump to
//                       the Issues tab (Jayden's exception flow).
//
// Uses only tokens.css variables + the same S.* style contract Vimal passes in,
// so it visually matches his scanner with no foreign styling.

import { useEffect, useRef, useState, useCallback } from "react";
import { QrCode, CheckCircle2, AlertTriangle, RefreshCw } from "lucide-react";
import jsQR from "jsqr";
import { apiPost } from "../../lib/api.js";

const TRIP_ID = "t-1";

export default function JaydenQrScanner({ coachLabel, onCheckedIn, onLogException }) {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const rafRef = useRef(0);
  const streamRef = useRef(null);
  const lastRef = useRef({ code: null, at: 0 });

  const [camError, setCamError] = useState("");
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState(null); // { ok, title, sub, offerLog }

  const show = useCallback((r) => {
    setResult(r);
    if (r.ok) setTimeout(() => setResult(null), 3000);
  }, []);

  // Check a decoded delegate in through Jayden's own manual endpoint.
  const checkIn = useCallback(async (delegateId) => {
    setBusy(true);
    try {
      const res = await apiPost("/checkins/manual", {
        tripId: TRIP_ID,
        delegateId,
        clientEventId: crypto.randomUUID(),
        clientTs: new Date().toISOString(),
      });
      if (res.duplicate) {
        show({ ok: true, title: "Already checked in", sub: `${delegateId} was already marked present` });
      } else {
        show({ ok: true, title: "Checked in", sub: `${res.delegateId || delegateId} · marked present` });
      }
      onCheckedIn?.();
    } catch (e) {
      if (e.status === 404) {
        // Unknown delegate id encoded in the badge -> exception territory.
        show({
          ok: false,
          title: "Badge not on this trip",
          sub: "This delegate isn't in the roster. Log an exception instead.",
          offerLog: true,
        });
      } else {
        show({ ok: false, title: "Check-in failed", sub: e.message || "Try again.", offerLog: true });
      }
    } finally {
      setBusy(false);
    }
  }, [onCheckedIn, show]);

  // Validate a decoded QR string, then act on it.
  const handleDecode = useCallback((text) => {
    const now = Date.now();
    if (lastRef.current.code === text && now - lastRef.current.at < 3500) return; // debounce
    lastRef.current = { code: text, at: now };
    if (busy) return;

    let payload;
    try { payload = JSON.parse(text); } catch { payload = null; }
    const valid = payload && payload.t === "mg-checkin" && payload.delegateId;
    if (!valid) {
      show({
        ok: false,
        title: "Badge not recognised",
        sub: "QR is damaged or not a MusterGo badge.",
        offerLog: true,
      });
      return;
    }
    checkIn(payload.delegateId);
  }, [busy, checkIn, show]);

  // Camera + scan loop.
  useEffect(() => {
    let cancelled = false;
    async function start() {
      try {
        setCamError("");
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "environment" }, audio: false,
        });
        if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return; }
        streamRef.current = stream;
        const v = videoRef.current;
        if (v) { v.srcObject = stream; v.setAttribute("playsinline", "true"); await v.play().catch(() => {}); }
        tick();
      } catch {
        if (!cancelled) setCamError("Camera unavailable — allow camera access, or use Manual / Log exception.");
      }
    }
    function tick() {
      const v = videoRef.current, c = canvasRef.current;
      if (v && c && v.readyState === v.HAVE_ENOUGH_DATA) {
        const ctx = c.getContext("2d", { willReadFrequently: true });
        c.width = v.videoWidth; c.height = v.videoHeight;
        ctx.drawImage(v, 0, 0, c.width, c.height);
        const img = ctx.getImageData(0, 0, c.width, c.height);
        const code = jsQR(img.data, img.width, img.height, { inversionAttempts: "dontInvert" });
        if (code && code.data) handleDecode(code.data);
      }
      rafRef.current = requestAnimationFrame(tick);
    }
    start();
    return () => {
      cancelled = true;
      cancelAnimationFrame(rafRef.current);
      streamRef.current?.getTracks().forEach((t) => t.stop());
    };
  }, [handleDecode]);

  return (
    <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 14 }}>
      {!camError ? (
        <div style={{ position: "relative", width: 150, height: 150, borderRadius: 12, overflow: "hidden", background: "#000" }}>
          <video ref={videoRef} muted playsInline style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          <span className="vimal-corner tl" /><span className="vimal-corner tr" />
          <span className="vimal-corner bl" /><span className="vimal-corner br" />
          {busy && <span className="vimal-scanline" />}
        </div>
      ) : (
        <div style={{ width: 140, height: 140, borderRadius: 12, border: "2px dashed var(--ink-2)", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <QrCode size={52} style={{ opacity: 0.7 }} />
        </div>
      )}
      <canvas ref={canvasRef} style={{ display: "none" }} />

      <div style={{ fontWeight: 600, color: "var(--surface)", marginTop: 12 }}>QR check-in{coachLabel ? ` · ${coachLabel}` : ""}</div>
      <div style={{ fontSize: 12.5, color: "var(--line)", maxWidth: 240, textAlign: "center", marginTop: 4 }}>
        {camError || "Hold the delegate's badge inside the frame."}
      </div>

      {result && (
        <div
          className="card vimal-toast"
          style={{
            marginTop: 12, padding: "10px 14px", width: "88%", color: "var(--ink)",
            borderLeft: `4px solid ${result.ok ? "var(--st-present)" : "var(--scc-red)"}`,
          }}
        >
          <div className="row" style={{ gap: 10, alignItems: "flex-start" }}>
            {result.ok
              ? <CheckCircle2 size={22} style={{ color: "var(--st-present)", flexShrink: 0 }} />
              : <AlertTriangle size={22} style={{ color: "var(--scc-red)", flexShrink: 0 }} />}
            <div style={{ textAlign: "left", flex: 1 }}>
              <div style={{ fontWeight: 700, fontSize: 14 }}>{result.title}</div>
              <div className="muted" style={{ fontSize: 12.5 }}>{result.sub}</div>
              {result.offerLog && (
                <button className="btn btn-primary" style={{ marginTop: 8, padding: "6px 12px", fontSize: 13 }}
                  onClick={() => onLogException?.()}>
                  Log exception
                </button>
              )}
            </div>
            {!result.ok && (
              <button className="btn btn-ghost" style={{ padding: 6 }} title="Dismiss" onClick={() => setResult(null)}>
                <RefreshCw size={14} />
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

