          video: { facingMode: "environment" }, audio: false,
        });
        if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return; }
        streamRef.current = stream;
        const v = videoRef.current;
        if (v) { v.srcObject = stream; v.setAttribute("playsinline", "true"); await v.play().catch(() => {}); }
        tick();
      } catch {
        if (!cancelled) setCamError("Camera unavailable — allow camera access, or use Manual / Log exception.");
      }
    }
    function tick() {
      const v = videoRef.current, c = canvasRef.current;
      if (v && c && v.readyState === v.HAVE_ENOUGH_DATA) {
        const ctx = c.getContext("2d", { willReadFrequently: true });
        c.width = v.videoWidth; c.height = v.videoHeight;
        ctx.drawImage(v, 0, 0, c.width, c.height);
        const img = ctx.getImageData(0, 0, c.width, c.height);
        const code = jsQR(img.data, img.width, img.height, { inversionAttempts: "dontInvert" });
        if (code && code.data) handleDecode(code.data);
      }
      rafRef.current = requestAnimationFrame(tick);
    }
    start();
    return () => {
      cancelled = true;
      cancelAnimationFrame(rafRef.current);
      streamRef.current?.getTracks().forEach((t) => t.stop());
    };
  }, [handleDecode]);

  return (
    <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 14 }}>
      {!camError ? (
        <div style={{ position: "relative", width: 150, height: 150, borderRadius: 12, overflow: "hidden", background: "#000" }}>
          <video ref={videoRef} muted playsInline style={{ width: "100%", height: "100%", objectFit: "cover" }} />
          <span className="vimal-corner tl" /><span className="vimal-corner tr" />
          <span className="vimal-corner bl" /><span className="vimal-corner br" />
          {busy && <span className="vimal-scanline" />}
        </div>
      ) : (
        <div style={{ width: 140, height: 140, borderRadius: 12, border: "2px dashed var(--ink-2)", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <QrCode size={52} style={{ opacity: 0.7 }} />
        </div>
      )}
      <canvas ref={canvasRef} style={{ display: "none" }} />

      <div style={{ fontWeight: 600, color: "var(--surface)", marginTop: 12 }}>QR check-in{coachLabel ? ` · ${coachLabel}` : ""}</div>
      <div style={{ fontSize: 12.5, color: "var(--line)", maxWidth: 240, textAlign: "center", marginTop: 4 }}>
        {camError || "Hold the delegate's badge inside the frame."}
      </div>

      {result && (
        <div
          className="card vimal-toast"
          style={{
            marginTop: 12, padding: "10px 14px", width: "88%", color: "var(--ink)",
            borderLeft: `4px solid ${result.ok ? "var(--st-present)" : "var(--scc-red)"}`,
          }}
        >
          <div className="row" style={{ gap: 10, alignItems: "flex-start" }}>
            {result.ok
              ? <CheckCircle2 size={22} style={{ color: "var(--st-present)", flexShrink: 0 }} />
              : <AlertTriangle size={22} style={{ color: "var(--scc-red)", flexShrink: 0 }} />}
            <div style={{ textAlign: "left", flex: 1 }}>
              <div style={{ fontWeight: 700, fontSize: 14 }}>{result.title}</div>
              <div className="muted" style={{ fontSize: 12.5 }}>{result.sub}</div>
              {result.offerLog && (
                <button className="btn btn-primary" style={{ marginTop: 8, padding: "6px 12px", fontSize: 13 }}
                  onClick={() => onLogException?.()}>
                  Log exception
                </button>
              )}
            </div>
            {!result.ok && (
              <button className="btn btn-ghost" style={{ padding: 6 }} title="Dismiss" onClick={() => setResult(null)}>
                <RefreshCw size={14} />
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
