// frontend/src/pages/checkin/JaydenIssuesPanel.jsx
// OWNED BY: Jayden — on-ground Log Exception (Issues tab of Vimal's check-in app).
//
// Replaces the placeholder Issues stub. Lets on-ground staff raise an exception
// (Missing person / Lost badge / Dead phone / VIP request) against a delegate,
// optionally CRITICAL — which the backend fans out to all staff devices over
// SSE. Uses Jayden's already-merged endpoint POST /api/trips/:id/exceptions.
//
// It accepts an optional `prefillDelegate` so Vimal's "phone" icon on a missing
// delegate can jump straight here with that delegate pre-selected.
//
// Styling: tokens.css + the S.* object Vimal already uses, passed in as `S`.

import { useEffect, useState } from "react";
import { UserX, BadgeX, BatteryLow, Accessibility, CheckCircle2, AlertTriangle } from "lucide-react";
import { apiGet, apiPost } from "../../lib/api.js";

const TRIP_ID = "t-1";
const ISSUES = [
  { value: "MISSING_PERSON", label: "Missing person", Icon: UserX },
  { value: "LOST_BADGE",     label: "Lost badge",     Icon: BadgeX },
  { value: "DEAD_PHONE",     label: "Dead phone",     Icon: BatteryLow },
  { value: "VIP_REQUEST",    label: "VIP request",    Icon: Accessibility },
];

export default function JaydenIssuesPanel({ prefillDelegate }) {
  const [delegates, setDelegates] = useState([]);
  const [type, setType] = useState("MISSING_PERSON");
  const [delegateId, setDelegateId] = useState(prefillDelegate || "");
  const [note, setNote] = useState("");
  const [critical, setCritical] = useState(false);
  const [saving, setSaving] = useState(false);
  const [done, setDone] = useState(null);   // { critical }
  const [error, setError] = useState("");

  useEffect(() => {
    apiGet(`/trips/${TRIP_ID}/delegates`)
      .then((d) => setDelegates(d.delegates || []))
      .catch(() => setDelegates([]));
  }, []);
  useEffect(() => { if (prefillDelegate) setDelegateId(prefillDelegate); }, [prefillDelegate]);

  async function submit() {
    setSaving(true); setError("");
    try {
      await apiPost(`/trips/${TRIP_ID}/exceptions`, {
        type,
        delegateId: delegateId || null,
        note: note || null,
        priority: critical ? "CRITICAL" : "NORMAL",
        clientEventId: crypto.randomUUID(),
      });
      setDone({ critical });
      setNote(""); setCritical(false);
      setTimeout(() => setDone(null), 3200);
    } catch (e) {
      setError(e.message || "Could not log the exception.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div>
      <div style={{ fontWeight: 700, fontSize: 18 }}>Log exception</div>
      <div className="muted" style={{ fontSize: 13, marginTop: 2, marginBottom: 14 }}>
        Raise an on-ground issue. Critical alerts notify every staff device instantly.
      </div>

      {done && (
        <div className="card vimal-toast" style={{ padding: "10px 14px", marginBottom: 12, borderLeft: "4px solid var(--st-present)" }}>
          <div className="row" style={{ gap: 10 }}>
            <CheckCircle2 size={20} style={{ color: "var(--st-present)", flexShrink: 0 }} />
            <div style={{ fontSize: 13.5, fontWeight: 600 }}>
              {done.critical ? "Critical alert sent to all staff devices" : "Exception logged"}
            </div>
          </div>
        </div>
      )}

      <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.06em", textTransform: "uppercase", color: "var(--ink-3)", marginBottom: 8 }}>
        Issue type
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10 }}>
        {ISSUES.map(({ value, label, Icon }) => {
          const on = type === value;
          return (
            <button key={value} onClick={() => setType(value)} aria-pressed={on}
              style={{
                display: "flex", flexDirection: "column", alignItems: "center", gap: 6,
                padding: "14px 8px", borderRadius: "var(--r-md)", fontSize: 13, fontWeight: 600,
                border: `1.5px solid ${on ? "var(--scc-red)" : "var(--line)"}`,
                background: on ? "var(--scc-red-tint)" : "var(--surface)",
                color: on ? "var(--scc-red-700)" : "var(--ink-2)",
              }}>
              <Icon size={20} /> {label}
            </button>
          );
        })}
      </div>

      <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.06em", textTransform: "uppercase", color: "var(--ink-3)", margin: "18px 0 8px" }}>
        Delegate
      </div>
      <select className="input" value={delegateId} onChange={(e) => setDelegateId(e.target.value)}>
        <option value="">Unidentified / not listed</option>
        {delegates.map((d) => (
          <option key={d.id} value={d.id}>{d.name}{d.vip ? " · VIP" : ""}</option>
        ))}
      </select>

      <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.06em", textTransform: "uppercase", color: "var(--ink-3)", margin: "18px 0 8px" }}>
        Quick note
      </div>
      <textarea className="input" rows={3} placeholder="What happened?" value={note}
        onChange={(e) => setNote(e.target.value)} style={{ resize: "vertical" }} />

      <button
        onClick={() => setCritical((v) => !v)} role="switch" aria-checked={critical}
        style={{
          display: "flex", alignItems: "center", gap: 12, width: "100%", marginTop: 16,
          padding: 14, borderRadius: "var(--r-md)", textAlign: "left",
          border: "1.5px solid var(--scc-red-tint-2)", background: "var(--scc-red-tint)",
        }}>
        <span style={{ width: 44, height: 26, borderRadius: 999, position: "relative", flexShrink: 0, background: critical ? "var(--scc-red)" : "var(--line)", transition: "background .15s" }}>
          <span style={{ position: "absolute", top: 3, left: critical ? 21 : 3, width: 20, height: 20, borderRadius: "50%", background: "var(--surface)", transition: "left .15s" }} />
        </span>
        <span>
          <div style={{ fontWeight: 700, color: "var(--scc-red-700)" }}>Mark as critical</div>
          <div style={{ fontSize: 13, color: "var(--scc-red-700)" }}>Alerts all staff devices instantly</div>
        </span>
      </button>

      {error && (
        <div className="row" style={{ gap: 8, color: "var(--scc-red-700)", fontSize: 13, marginTop: 10 }}>
          <AlertTriangle size={14} /> {error}
        </div>
      )}

      <button className="btn btn-primary btn-block" style={{ marginTop: 16 }} onClick={submit} disabled={saving}>
        {saving ? "Sending…" : critical ? "Submit & alert team" : "Submit exception"}
      </button>
    </div>
  );
}

