  let coach = coachId || null;
  if (!coach && delegateId) {
    const d = await q('SELECT "coachId" FROM delegates WHERE id = $1', [delegateId]);
    coach = d.rows[0]?.coachId || null;
  }

  const id = randomUUID();
  const pri = ["CRITICAL", "NORMAL", "LOW"].includes(priority) ? priority : "NORMAL";
  await q(
