cat > /tmp/ui2.mjs << 'EOF'
import pkg from "/home/claude/.npm-global/lib/node_modules/playwright/index.js";
const { chromium } = pkg;
import { mkdirSync } from "fs";
const OUT = "/home/claude/mustergo-final/shots2"; mkdirSync(OUT, { recursive: true });
const b = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium-1194/chrome-linux/chrome", args: ["--no-sandbox","--use-fake-ui-for-media-stream","--use-fake-device-for-media-stream"] });
const ctx = await b.newContext({ viewport: { width: 1380, height: 1000 }, deviceScaleFactor: 2, permissions: ["camera"] });
const p = await ctx.newPage();
const fails=[]; const ok=(c,m)=>{console.log((c?"PASS  ":"FAIL  ")+m); if(!c)fails.push(m);};
p.on("pageerror", e => console.log("  [pageerror]", String(e).slice(0,140)));

await p.goto("http://localhost:5173/", { waitUntil: "domcontentloaded" });
await p.waitForTimeout(1500);
await p.fill('input#staffId, input[name="staffId"], input[type="text"]', "staff_194").catch(()=>{});
const pw = await p.$('input[type="password"]'); if (pw) await pw.fill("password123!");
await p.getByRole("button", { name: "Sign in", exact: true }).click();
await p.waitForTimeout(2500);

/* ================= ADMIN ================= */
await p.goto("http://localhost:5173/exceptions", { waitUntil: "domcontentloaded" });
await p.waitForTimeout(3000);
await p.getByRole("button", { name: /Log exception/ }).click();
await p.waitForTimeout(1200);

let body = await p.innerText(".exc-modal");
ok(/Others/.test(body), "ADMIN: 'Others' tile present");
ok(/Priority/.test(body), "ADMIN: Priority section present");
const prio = await p.$$eval(".exc-prio-btn", els => els.map(e=>e.innerText.trim()));
console.log("      priority buttons:", prio.join(" | "));
ok(prio.length===2 && /Normal/i.test(prio[0]) && /Low/i.test(prio[1]), "ADMIN: Normal + Low buttons render");

// colour-coding: selected Normal should be violet
await p.$$eval(".exc-prio-btn", els => els.find(e=>/Normal/i.test(e.innerText)).click());
await p.waitForTimeout(400);
let c = await p.$$eval(".exc-prio-btn", els => { const e=els.find(x=>/Normal/i.test(x.innerText)); const s=getComputedStyle(e); return {color:s.color, border:s.borderColor}; });
console.log("      Normal selected colour:", c.color);
ok(c.color.includes("124, 58, 237"), "ADMIN: Normal is violet (--st-normal)");

await p.$$eval(".exc-prio-btn", els => els.find(e=>/Low/i.test(e.innerText)).click());
await p.waitForTimeout(400);
c = await p.$$eval(".exc-prio-btn", els => { const e=els.find(x=>/Low/i.test(x.innerText)); const s=getComputedStyle(e); return {color:s.color}; });
console.log("      Low selected colour:", c.color);
ok(c.color.includes("107, 114, 128"), "ADMIN: Low is slate (--st-neutral)");

// Others -> input appears with counter + maxlength
await p.$$eval(".exc-issue-opt", els => els.find(e=>/Others/.test(e.innerText)).click());
await p.waitForTimeout(600);
const inp = await p.$("#exc-type-other");
ok(!!inp, "ADMIN: Others reveals the free-text input");
const maxlen = await p.getAttribute("#exc-type-other", "maxlength");
ok(maxlen === "20", `ADMIN: input capped at 20 chars (maxlength=${maxlen})`);
await p.fill("#exc-type-other", "Lost luggage");
await p.waitForTimeout(300);
body = await p.innerText(".exc-modal");
ok(/12\/20/.test(body), "ADMIN: live character counter works");
// overtype past the cap
await p.fill("#exc-type-other", "");
await p.type("#exc-type-other", "ABCDEFGHIJKLMNOPQRSTUVWXYZ", { delay: 5 });
const val = await p.inputValue("#exc-type-other");
ok(val.length === 20, `ADMIN: browser enforces the cap (typed 26, kept ${val.length})`);

// critical supersedes
await p.$$eval(".exc-critical", els => els[0].click());
await p.waitForTimeout(500);
const disabled = await p.$$eval(".exc-prio-btn", els => els.every(e => e.disabled));
ok(disabled, "ADMIN: Critical ON disables Normal/Low (it supersedes)");
await p.screenshot({ path: `${OUT}/1-admin-modal.png` });
await p.$$eval(".exc-critical", els => els[0].click());  // back off
await p.waitForTimeout(400);

// submit an Others + Low ticket for real
await p.fill("#exc-type-other", "UI test label");
await p.$$eval(".exc-prio-btn", els => els.find(e=>/Low/i.test(e.innerText)).click());
await p.waitForTimeout(300);
await p.getByRole("button", { name: /Submit ticket/ }).click();
await p.waitForTimeout(2800);
body = await p.innerText("body");
ok(/UI test label/.test(body), "ADMIN: custom label shows in the inbox list (not 'Other')");
const lowBadge = await p.$$eval(".badge", els => els.some(e => /^Low$/i.test(e.innerText.trim())));
ok(lowBadge, "ADMIN: Low priority pill renders in the list");
await p.screenshot({ path: `${OUT}/2-admin-list.png`, fullPage: true });

/* ================= MOBILE ================= */
await p.goto("http://localhost:5173/checkin", { waitUntil: "domcontentloaded" });
await p.waitForTimeout(2500);
const issIdx = await p.$$eval("button", els => els.findIndex(e=>/^issues$/i.test(e.innerText.trim())));
if (issIdx>=0) { (await p.$$("button"))[issIdx].click(); await p.waitForTimeout(2000); }
body = await p.innerText("body");
ok(/Others/.test(body), "MOBILE: 'Others' tile present");
ok(/Priority/.test(body), "MOBILE: Priority section present");
const mprio = await p.$$eval("button", els => els.filter(e=>/^(Normal|Low)$/i.test(e.innerText.trim())).map(e=>e.innerText.trim()));
console.log("      mobile priority buttons:", mprio.join(" | "));
ok(mprio.length===2, "MOBILE: Normal + Low buttons render");

// Others reveals input
await p.$$eval("button", els => { const e = els.find(x=>/^Others$/.test(x.innerText.trim())); if(e) e.click(); });
await p.waitForTimeout(700);
const mInp = await p.$('input[aria-label="Describe the issue type"]');
ok(!!mInp, "MOBILE: Others reveals the free-text input");
const mMax = await p.getAttribute('input[aria-label="Describe the issue type"]', "maxlength");
ok(mMax === "20", `MOBILE: input capped at 20 (maxlength=${mMax})`);
await p.fill('input[aria-label="Describe the issue type"]', "Wrong hotel");
await p.waitForTimeout(300);
body = await p.innerText("body");
ok(/11\/20/.test(body), "MOBILE: live character counter works");
await p.screenshot({ path: `${OUT}/3-mobile-form.png`, fullPage: true });

// pick Low, submit
await p.$$eval("button", els => { const e = els.find(x=>/^Low$/i.test(x.innerText.trim())); if(e) e.click(); });
await p.waitForTimeout(300);
await p.$$eval("button", els => { const e = els.find(x=>/^Submit ticket$/i.test(x.innerText.trim())); if(e) e.click(); });
await p.waitForTimeout(3000);
body = await p.innerText("body");
ok(/Wrong hotel/.test(body), "MOBILE: custom label appears in the open-tickets list");
ok(/\bLow\b/.test(body), "MOBILE: Low pill renders (was previously mislabelled 'Normal')");
await p.screenshot({ path: `${OUT}/4-mobile-list.png`, fullPage: true });

await b.close();
console.log(fails.length ? `\n${fails.length} FAILED` : "\nALL FEATURE UI CHECKS PASSED");
process.exit(fails.length?1:0);
EOF

